              )}
            >
              <ArrowUp className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Keyboard hint */}
        <div className="flex items-center justify-between px-4 pb-2.5 pt-0 text-[10px] text-muted-foreground/50 select-none">
          <span>Enter to send · Shift + Enter for new line</span>
        </div>
