"use client";

import React, { useState, useRef, useEffect } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  Copy,
  Share2,
  Pin,
  FolderInput,
  Trash2,
  MoreHorizontal,
  Check,
} from "lucide-react";
