export function AutoplayStoryCarousel({
  slides = DEFAULT_SLIDES,
  duration = 5000,
  defaultIndex = 0,
  autoPlay = true,
  onSlideChange,
  showHeader = true,
  showControls = true,
  className,
}: AutoplayStoryCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(defaultIndex);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [isMuted, setIsMuted] = useState(true);
  const [progress, setProgress] = useState(0);
  const [slideDuration, setSlideDuration] = useState(duration);
  const [direction, setDirection] = useState(1);

  const isPausedRef = useRef(false);
  const progressStartTimeRef = useRef(Date.now());
  const elapsedBeforePauseRef = useRef(0);

  const total = slides.length;
  const currentSlide = slides[currentIndex];

  const nextSlide = useCallback(() => {
    setDirection(1);
    setProgress(0);
    elapsedBeforePauseRef.current = 0;
    progressStartTimeRef.current = Date.now();
    setCurrentIndex((prev) => {
      const next = (prev + 1) % total;
      onSlideChange?.(next);
      return next;
    });
  }, [total, onSlideChange]);

  const prevSlide = useCallback(() => {
    setDirection(-1);
    setProgress(0);
    elapsedBeforePauseRef.current = 0;
    progressStartTimeRef.current = Date.now();
    setCurrentIndex((prev) => {
      const next = (prev - 1 + total) % total;
      onSlideChange?.(next);
      return next;
    });
  }, [total, onSlideChange]);

  // Autoplay ticker loop with high-resolution timestamp calculation
  useEffect(() => {
    if (!isPlaying) return;

    let animId: number;
    progressStartTimeRef.current = Date.now() - elapsedBeforePauseRef.current;

    const loop = () => {
      if (!isPausedRef.current) {
        const elapsed = Date.now() - progressStartTimeRef.current;
        const currentP = Math.min(100, (elapsed / slideDuration) * 100);
        setProgress(currentP);

        if (elapsed >= slideDuration) {
          nextSlide();
          return;
        }
      }
      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [currentIndex, isPlaying, slideDuration, nextSlide]);

  const handlePointerDown = () => {
    isPausedRef.current = true;
    elapsedBeforePauseRef.current = (progress / 100) * slideDuration;
  };

  const handlePointerUp = () => {
    isPausedRef.current = false;
    progressStartTimeRef.current = Date.now() - elapsedBeforePauseRef.current;
  };

  const handleContainerClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    if (clickX < rect.width * 0.4) {
      prevSlide();
    } else {
      nextSlide();
    }
  };

  // Jump to specific slide
  const goToSlide = (index: number) => {
    setDirection(index > currentIndex ? 1 : -1);
    setProgress(0);
    elapsedBeforePauseRef.current = 0;
    progressStartTimeRef.current = Date.now();
    setCurrentIndex(index);
    onSlideChange?.(index);
  };

  // Slide transition variants
  const slideVariants = {
    enter: (dir: number) => ({
      x: dir > 0 ? 120 : -120,
      opacity: 0,
      scale: 0.95,
    }),
    center: {
      x: 0,
      opacity: 1,
      scale: 1,
      transition: {
        x: { type: "spring", stiffness: 350, damping: 30 },
        opacity: { duration: 0.28 },
        scale: { duration: 0.28 },
      },
    },
    exit: (dir: number) => ({
      x: dir > 0 ? -120 : 120,
      opacity: 0,
