                  {currentSlide.date}
                </span>
              </div>

              {/* Main Content Body */}
              <div className="space-y-3">
                <div className="inline-block rounded-md bg-white/10 px-2 py-0.5 text-[10px] font-mono text-white/90">
                  {currentSlide.badge}
