  const shouldReduceMotion = useReducedMotion() ?? false;
  const [mode, setMode] = useState<IslandMode>(defaultMode);

  const cycleMode = () => {
    setMode((prev) =>
      prev === "compact"
        ? "telemetry"
        : prev === "telemetry"
          ? "expanded"
          : "compact"
