}

export function ElasticDock({
  items = DEFAULT_ITEMS,
  baseSize = 46,
  magnifiedSize = 68,
  distance = 140,
  stiffness = 320,
  damping = 22,
  defaultActiveId = "kinetic",
  onSelect,
  className,
}: ElasticDockProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const mouseX = useMotionValue(-Infinity);
  const [activeId, setActiveId] = useState<string>(
    defaultActiveId || items[0]?.id || ""
  );
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const handleKeyDown = (
    index: number,
    e: React.KeyboardEvent<HTMLButtonElement>
  ) => {
    if (e.key === "ArrowRight") {
      e.preventDefault();
      const next = (index + 1) % items.length;
      buttonRefs.current[next]?.focus();
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      const prev = (index - 1 + items.length) % items.length;
      buttonRefs.current[prev]?.focus();
    } else if (e.key === "Home") {
      e.preventDefault();
      buttonRefs.current[0]?.focus();
    } else if (e.key === "End") {
      e.preventDefault();
      buttonRefs.current[items.length - 1]?.focus();
    }
  };

  return (
    <motion.div
      role="toolbar"
      aria-label="Application dock navigation"
      onMouseMove={(e) => {
        if (!shouldReduceMotion) {
          mouseX.set(e.clientX);
        }
      }}
      onMouseLeave={() => mouseX.set(-Infinity)}
      className={cn(
        "inline-flex items-end gap-2.5 rounded-3xl border border-neutral-200/90 bg-white/85 px-4 pb-2 pt-3 shadow-sm backdrop-blur-xl dark:border-[#222222] dark:bg-[#0A0A0A]/85",
        className
      )}
    >
      {items.map((item, idx) => (
        <DockIconButton
          key={item.id}
          item={item}
          isActive={activeId === item.id}
          mouseX={mouseX}
          baseSize={baseSize}
          magnifiedSize={magnifiedSize}
          distance={distance}
          stiffness={stiffness}
          damping={damping}
          shouldReduceMotion={shouldReduceMotion}
          onSelect={() => {
            setActiveId(item.id);
            onSelect?.(item.id);
          }}
          onKeyNav={(e) => handleKeyDown(idx, e)}
          buttonRef={(el) => {
            buttonRefs.current[idx] = el;
          }}
        />
      ))}
    </motion.div>
  );
}

export default ElasticDock;

