  size: number;
  yaw: number;
  pitch: number;
  roll: number;
  yawSpeed: number;
  pitchSpeed: number;
  rollSpeed: number;
  glidePhase: number;
  glideFreq: number;
  glideSpan: number;
  colorIndex: number;
}

const VARIANT_PALETTES: Record<
  PetalVariant,
  {
    label: string;
    bgTop: string;
    bgMid: string;
    bgBottom: string;
    sunbeam: string;
    colors: [string, string, string][];
