    const angle = (i * (360 / 12)) + (i % 2 === 0 ? 8 : -8);
    const distance = 28 + (i % 3) * 10;
    const pSize = 4 + (i % 3) * 2;
    const color = colors.particles[i % colors.particles.length];
    return { id: i, angle, distance, size: pSize, color };
