    bgBottom: "#1B0933",
    smogGlow: "rgba(236, 72, 153, 0.20)",
    gridLine: "rgba(236, 72, 153, 0.22)",
    streetGlow: "rgba(34, 211, 238, 0.14)",
    roofFace: "#271340",
    leftFace: "#170A29",
    rightFace: "#0D041A",
    edgeStroke: "rgba(244, 114, 182, 0.32)",
    neonAccent: "#22D3EE",
    windowLitA: "#22D3EE",
    windowLitB: "#F472B6",
    beaconColor: "#22D3EE",
    headlight: "#22D3EE",
    taillight: "#F43F5E",
  },
  amber: {
