          }}
          className="absolute bottom-[5%] left-[15%] h-72 w-72 rounded-full"
        />
        <div
          style={{
            background: c[3],
            animation: `bose-mesh-orbit-4 ${dur * 1.35}s ease-in-out infinite`,
          }}
          className="absolute bottom-[8%] right-[12%] h-72 w-72 rounded-full"
        />
        {c[4] && (
          <div
            style={{
