import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

export interface MovingGridLinesProps {
  /** Size of each square grid cell in pixels. Default: 64 */
  gridSize?: number;
  /** Number of concurrent moving beams. Default: 8 */
  beamCount?: number;
  /** Length of the light beam trail in pixels. Default: 160 */
  beamLength?: number;
  /** Speed multiplier for the traveling beams. Default: 1.5 */
  speed?: number;
  /** Explicit grid line color. Defaults to adaptive light/dark mode color */
  gridColor?: string;
  /** Explicit beam light color. Defaults to adaptive light/dark mode beam color */
  beamColor?: string;
  /** Whether to apply a radial vignette mask fading edges to transparency. Default: true */
  radialMask?: boolean;
  /** Optional foreground content rendered above the moving grid surface */
  children?: React.ReactNode;
  /** Optional container CSS classes */
  className?: string;
}

interface GridBeam {
  id: number;
  direction: "horizontal" | "vertical";
  track: number; // Y coordinate for horizontal, X coordinate for vertical
  pos: number; // Current head position along the track
  startPos: number;
  endPos: number;
  speed: number;
  length: number;
  reverse: boolean;
  delay: number;
  opacity: number;
}

export function MovingGridLines({
  gridSize = 64,
  beamCount = 8,
  beamLength = 160,
  speed = 1.5,
  gridColor,
  beamColor,
  radialMask = true,
  children,
  className,
}: MovingGridLinesProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [isReducedMotion, setIsReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    setIsReducedMotion(mediaQuery.matches);
    const handleChange = (e: MediaQueryListEvent) => setIsReducedMotion(e.matches);
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let width = 0;
    let height = 0;
    let dpr = 1;

    // Detect theme color adaptively
    const getThemeColors = () => {
      const isDark = document.documentElement.classList.contains("dark");
      const defaultGrid = isDark
        ? "rgba(255, 255, 255, 0.05)"
        : "rgba(0, 0, 0, 0.05)";
      const defaultBeam = isDark
        ? "rgba(255, 255, 255, 0.85)"
        : "rgba(0, 0, 0, 0.75)";

      return {
        resolvedGridColor: gridColor || defaultGrid,
        resolvedBeamColor: beamColor || defaultBeam,
      };
    };

    let colors = getThemeColors();

    // Observe theme toggle on html tag
    const themeObserver = new MutationObserver(() => {
      colors = getThemeColors();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const createBeam = (id: number): GridBeam => {
      const isHorizontal = Math.random() > 0.5;
      const length = beamLength * (0.8 + Math.random() * 0.5);
      const beamSpeed = (120 + Math.random() * 140) * speed;
      const reverse = Math.random() > 0.5;

      if (isHorizontal) {
        const rows = Math.max(1, Math.floor(height / gridSize));
        const rowIndex = Math.floor(Math.random() * (rows + 1));
        const track = rowIndex * gridSize;

        return {
          id,
          direction: "horizontal",
          track,
          pos: reverse ? width + length : -length,
          startPos: reverse ? width + length : -length,
          endPos: reverse ? -length : width + length,
          speed: beamSpeed,
          length,
          reverse,
          delay: Math.random() * 2,
          opacity: 0.6 + Math.random() * 0.4,
        };
      } else {
        const cols = Math.max(1, Math.floor(width / gridSize));
        const colIndex = Math.floor(Math.random() * (cols + 1));
        const track = colIndex * gridSize;

        return {
          id,
          direction: "vertical",
          track,
          pos: reverse ? height + length : -length,
          startPos: reverse ? height + length : -length,
          endPos: reverse ? -length : height + length,
          speed: beamSpeed,
          length,
          reverse,
          delay: Math.random() * 2,
          opacity: 0.6 + Math.random() * 0.4,
        };
      }
    };

    let beams: GridBeam[] = [];

    const resize = () => {
      if (!container || !canvas) return;
      const rect = container.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      dpr = Math.min(window.devicePixelRatio || 1, 2);

      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      ctx.scale(dpr, dpr);

      // Re-initialize beams for new dimensions
      beams = Array.from({ length: beamCount }, (_, i) => createBeam(i));
    };

    resize();

    const resizeObserver = new ResizeObserver(() => {
      resize();
    });
    resizeObserver.observe(container);

    let lastTime = performance.now();

    const render = (time: number) => {
      const dt = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      ctx.clearRect(0, 0, width, height);

      // 1. Draw static crisp grid lines
      ctx.lineWidth = 1;
      ctx.strokeStyle = colors.resolvedGridColor;
      ctx.beginPath();

      // Vertical lines
      for (let x = 0; x <= width; x += gridSize) {
        ctx.moveTo(x + 0.5, 0);
        ctx.lineTo(x + 0.5, height);
      }

      // Horizontal lines
      for (let y = 0; y <= height; y += gridSize) {
        ctx.moveTo(0, y + 0.5);
        ctx.lineTo(width, y + 0.5);
      }
      ctx.stroke();

      // 2. Draw moving glowing beams (if not reduced motion)
      if (!isReducedMotion) {
        for (let i = 0; i < beams.length; i++) {
          const b = beams[i];

          if (b.delay > 0) {
            b.delay -= dt;
            continue;
          }

          // Advance beam position
          if (b.reverse) {
            b.pos -= b.speed * dt;
            if (b.pos < b.endPos) {
              beams[i] = createBeam(b.id);
              continue;
            }
          } else {
            b.pos += b.speed * dt;
            if (b.pos > b.endPos) {
              beams[i] = createBeam(b.id);
              continue;
            }
          }

          // Draw linear glowing gradient beam along track
          ctx.save();
          if (b.direction === "horizontal") {
            const headX = b.pos;
            const tailX = b.reverse ? headX + b.length : headX - b.length;

            const grad = ctx.createLinearGradient(tailX, b.track, headX, b.track);
            grad.addColorStop(0, "transparent");
            grad.addColorStop(
              0.8,
              colors.resolvedBeamColor.replace(
                /[\d.]+\)$/g,
                `${(b.opacity * 0.7).toFixed(2)})`
              )
            );
            grad.addColorStop(1, colors.resolvedBeamColor);

            ctx.strokeStyle = grad;
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(tailX, b.track + 0.5);
            ctx.lineTo(headX, b.track + 0.5);
            ctx.stroke();

            // Bright head spark
            ctx.fillStyle = colors.resolvedBeamColor;
            ctx.beginPath();
            ctx.arc(headX, b.track + 0.5, 1.5, 0, Math.PI * 2);
            ctx.fill();
          } else {
            const headY = b.pos;
            const tailY = b.reverse ? headY + b.length : headY - b.length;

            const grad = ctx.createLinearGradient(b.track, tailY, b.track, headY);
            grad.addColorStop(0, "transparent");
            grad.addColorStop(
              0.8,
              colors.resolvedBeamColor.replace(
                /[\d.]+\)$/g,
                `${(b.opacity * 0.7).toFixed(2)})`
              )
            );
            grad.addColorStop(1, colors.resolvedBeamColor);

            ctx.strokeStyle = grad;
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(b.track + 0.5, tailY);
            ctx.lineTo(b.track + 0.5, headY);
            ctx.stroke();

            // Bright head spark
            ctx.fillStyle = colors.resolvedBeamColor;
            ctx.beginPath();
            ctx.arc(b.track + 0.5, headY, 1.5, 0, Math.PI * 2);
            ctx.fill();
          }
          ctx.restore();
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
      themeObserver.disconnect();
    };
  }, [gridSize, beamCount, beamLength, speed, gridColor, beamColor, isReducedMotion]);

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative w-full overflow-hidden",
        radialMask &&
          "[mask-image:radial-gradient(ellipse_65%_55%_at_50%_25%,black_25%,transparent_100%)]",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 block h-full w-full"
      />
      {children && <div className="relative z-10">{children}</div>}
    </div>
  );
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useState, useRef, useEffect, useId, useMemo } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { X, Plus, Tag, Check } from "lucide-react";
import { cn } from "@/lib/utils";

export interface TagSuggestion {
  value: string;
  label: string;
  category?: string;
}

export interface MultiSelectTagInputProps {
  /** Suggested tags shown in the dropdown */
  suggestions?: TagSuggestion[];
  /** Controlled array of selected tag values */
  value?: string[];
  /** Initial selected tag values for uncontrolled mode */
  defaultValue?: string[];
  /** Callback fired whenever selected tags change */
  onChange?: (tags: string[]) => void;
  /** Input placeholder when empty */
  placeholder?: string;
  /** Optional field label */
  label?: string;
  /** Maximum number of tags allowed. Default: 8 */
  maxTags?: number;
  /** Allow creating custom tags not in suggestions by pressing Enter or comma. Default: true */
  allowCustomTags?: boolean;
  /** Disable input and tag removal */
  disabled?: boolean;
  className?: string;
}

const DEFAULT_SUGGESTIONS: TagSuggestion[] = [
  { value: "react", label: "React", category: "Frontend" },
  { value: "typescript", label: "TypeScript", category: "Language" },
  { value: "tailwind", label: "Tailwind CSS", category: "Styling" },
  { value: "framer-motion", label: "Framer Motion", category: "Animation" },
  { value: "nextjs", label: "Next.js", category: "Framework" },
  { value: "accessibility", label: "Accessibility (WAI-ARIA)", category: "UX" },
  { value: "design-systems", label: "Design Systems", category: "UI" },
  { value: "graphql", label: "GraphQL", category: "API" },
];

export function MultiSelectTagInput({
  suggestions = DEFAULT_SUGGESTIONS,
  value,
  defaultValue = ["react", "typescript", "framer-motion"],
  onChange,
  placeholder = "Add tag or select...",
  label = "Tech Stack Tags",
  maxTags = 8,
  allowCustomTags = true,
  disabled = false,
  className,
}: MultiSelectTagInputProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const listboxId = useId();
  const isControlled = value !== undefined;

  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const selectedTags = isControlled ? value : internalTags;

  const [inputValue, setInputValue] = useState("");
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const updateTags = (next: string[]) => {
    if (!isControlled) {
      setInternalTags(next);
    }
    onChange?.(next);
  };

  const getTagLabel = (val: string) => {
    const match = suggestions.find(
      (s) => s.value.toLowerCase() === val.toLowerCase()
    );
    return match ? match.label : val;
  };

  const filteredSuggestions = useMemo(() => {
    const q = inputValue.trim().toLowerCase();
    return suggestions.filter((item) => {
      const alreadySelected = selectedTags.some(
        (t) => t.toLowerCase() === item.value.toLowerCase()
      );
      if (alreadySelected) return false;
      if (!q) return true;
      return (
        item.label.toLowerCase().includes(q) ||
        item.value.toLowerCase().includes(q) ||
        (item.category?.toLowerCase().includes(q) ?? false)
      );
    });
  }, [suggestions, selectedTags, inputValue]);

  const isAtLimit = selectedTags.length >= maxTags;

  const addTag = (rawVal: string) => {
    if (disabled || isAtLimit) return;
    const trimmed = rawVal.trim().replace(/,+$/, "");
    if (!trimmed) return;

    // Check if matches existing suggestion value or label
    const existingSuggestion = suggestions.find(
      (s) =>
        s.value.toLowerCase() === trimmed.toLowerCase() ||
        s.label.toLowerCase() === trimmed.toLowerCase()
    );

    const normalizedValue = existingSuggestion
      ? existingSuggestion.value
      : trimmed;

    if (!existingSuggestion && !allowCustomTags) return;

    const isDuplicate = selectedTags.some(
      (t) => t.toLowerCase() === normalizedValue.toLowerCase()
    );
    if (isDuplicate) {
      setInputValue("");
      return;
    }

    updateTags([...selectedTags, normalizedValue]);
    setInputValue("");
    setActiveIndex(0);
    inputRef.current?.focus();
  };

  const removeTag = (tagToRemove: string) => {
    if (disabled) return;
    updateTags(selectedTags.filter((t) => t !== tagToRemove));
  };

  useEffect(() => {
    setActiveIndex(0);
  }, [inputValue]);

  useEffect(() => {
    if (!open || !listRef.current) return;
    const activeEl = listRef.current.querySelector<HTMLElement>(
      `[data-index="${activeIndex}"]`
    );
    activeEl?.scrollIntoView({ block: "nearest" });
  }, [activeIndex, open]);

  useEffect(() => {
    const handleOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handleOutside);
    return () => document.removeEventListener("mousedown", handleOutside);
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (disabled) return;

    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      if (filteredSuggestions.length > 0) {
        setActiveIndex((prev) => (prev + 1) % filteredSuggestions.length);
      }
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (filteredSuggestions.length > 0) {
        setActiveIndex(
          (prev) =>
            (prev - 1 + filteredSuggestions.length) %
            filteredSuggestions.length
        );
      }
    } else if (e.key === "Enter" || e.key === ",") {
      if (e.key === "," && !inputValue.trim()) {
        e.preventDefault();
        return;
      }
      if (open && filteredSuggestions[activeIndex] && !inputValue.endsWith(",")) {
        e.preventDefault();
        addTag(filteredSuggestions[activeIndex].value);
      } else if (inputValue.trim()) {
        e.preventDefault();
        addTag(inputValue);
      }
    } else if (
      e.key === "Backspace" &&
      inputValue === "" &&
      selectedTags.length > 0
    ) {
      e.preventDefault();
      removeTag(selectedTags[selectedTags.length - 1]);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={containerRef} className={cn("relative w-full max-w-md", className)}>
      {(label || maxTags) && (
        <div className="mb-1.5 flex items-center justify-between">
          {label && (
            <label
              onClick={() => inputRef.current?.focus()}
              className="cursor-pointer text-xs font-medium text-neutral-600 dark:text-neutral-400"
            >
              {label}
            </label>
          )}
          <div className="flex items-center gap-2">
            {selectedTags.length > 0 && !disabled && (
              <button
                type="button"
                onClick={() => updateTags([])}
                className="text-[11px] font-medium text-neutral-400 transition-colors hover:text-black dark:hover:text-white"
              >
                Clear all
              </button>
            )}
            <span
              className={cn(
                "font-mono text-[11px]",
                isAtLimit
                  ? "font-semibold text-amber-600 dark:text-amber-400"
                  : "text-neutral-400 dark:text-neutral-500"
              )}
            >
              {selectedTags.length}/{maxTags}
            </span>
          </div>
        </div>
      )}

      {/* Input & Tag Container */}
      <div
        onClick={() => {
          if (!disabled) {
            inputRef.current?.focus();
            setOpen(true);
          }
        }}
        className={cn(
          "flex min-h-[44px] w-full flex-wrap items-center gap-1.5 rounded-xl border bg-white p-2 transition-colors dark:bg-[#0A0A0A]",
          open
            ? "border-black ring-2 ring-black/10 dark:border-white dark:ring-white/10"
            : "border-neutral-200 hover:border-neutral-300 dark:border-[#262626] dark:hover:border-neutral-700",
          disabled && "cursor-not-allowed opacity-50"
        )}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          {selectedTags.map((tag) => (
            <motion.span
              key={tag}
              layout={!shouldReduceMotion}
              initial={
                shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.85 }
              }
              animate={{ opacity: 1, scale: 1 }}
              exit={
                shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.85 }
              }
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className="inline-flex items-center gap-1 rounded-lg border border-neutral-200 bg-neutral-100 px-2.5 py-1 text-xs font-medium text-black dark:border-[#262626] dark:bg-[#161616] dark:text-white"
            >
              <Tag className="h-3 w-3 text-neutral-400 dark:text-neutral-500" />
              <span>{getTagLabel(tag)}</span>
              {!disabled && (
                <button
                  type="button"
                  aria-label={`Remove ${getTagLabel(tag)}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    removeTag(tag);
                  }}
                  className="ml-0.5 rounded p-0.5 text-neutral-400 transition-colors hover:bg-neutral-200 hover:text-black dark:hover:bg-[#262626] dark:hover:text-white"
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </motion.span>
          ))}
        </AnimatePresence>

        <input
          ref={inputRef}
          type="text"
          role="combobox"
          aria-expanded={open}
          aria-controls={listboxId}
          aria-autocomplete="list"
          disabled={disabled || isAtLimit}
          value={inputValue}
          onFocus={() => setOpen(true)}
          onChange={(e) => {
            const val = e.target.value;
            if (val.endsWith(",")) {
              addTag(val);
            } else {
              setInputValue(val);
              setOpen(true);
            }
          }}
          onKeyDown={handleKeyDown}
          placeholder={
            isAtLimit
              ? "Maximum tags reached"
              : selectedTags.length === 0
                ? placeholder
                : "Add more..."
          }
          className="min-w-[110px] flex-1 bg-transparent px-1.5 py-0.5 text-sm text-black placeholder:text-neutral-400 focus:outline-none disabled:cursor-not-allowed dark:text-white dark:placeholder:text-neutral-600"
        />
      </div>

      {/* Helper hint */}
      <p className="mt-1.5 text-[11px] text-neutral-400 dark:text-neutral-500">
        Press <kbd className="rounded border border-neutral-200 bg-neutral-100 px-1 py-0.5 font-mono text-[10px] dark:border-neutral-800 dark:bg-neutral-900">Enter</kbd> or <kbd className="rounded border border-neutral-200 bg-neutral-100 px-1 py-0.5 font-mono text-[10px] dark:border-neutral-800 dark:bg-neutral-900">,</kbd> to add · <kbd className="rounded border border-neutral-200 bg-neutral-100 px-1 py-0.5 font-mono text-[10px] dark:border-neutral-800 dark:bg-neutral-900">Backspace</kbd> to remove
      </p>

      {/* Suggestions Dropdown */}
      <AnimatePresence>
        {open && !disabled && !isAtLimit && (
          <motion.div
            id={listboxId}
            ref={listRef}
            role="listbox"
            initial={
              shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }
            }
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={
              shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }
            }
            transition={{ type: "spring", stiffness: 420, damping: 28 }}
            className="absolute left-0 right-0 z-50 mt-1 max-h-52 overflow-y-auto rounded-xl border border-neutral-200 bg-white p-1.5 shadow-xl dark:border-[#262626] dark:bg-[#0A0A0A]"
          >
            {filteredSuggestions.length === 0 ? (
              allowCustomTags && inputValue.trim() ? (
                <button
                  type="button"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => addTag(inputValue)}
                  className="flex w-full items-center justify-between rounded-lg bg-neutral-100 px-3 py-2 text-left text-xs font-medium text-black dark:bg-[#161616] dark:text-white"
                >
                  <span className="flex items-center gap-2">
                    <Plus className="h-3.5 w-3.5" />
                    Create tag &ldquo;{inputValue.trim()}&rdquo;
                  </span>
                  <span className="font-mono text-[10px] text-neutral-400">
                    Enter
                  </span>
                </button>
              ) : (
                <div className="px-3 py-3 text-center text-xs text-neutral-400">
                  No matching suggestions available
                </div>
              )
            ) : (
              filteredSuggestions.map((item, idx) => {
                const isActive = idx === activeIndex;
                return (
                  <button
                    key={item.value}
                    type="button"
                    role="option"
                    data-index={idx}
                    aria-selected={isActive}
                    onMouseDown={(e) => e.preventDefault()}
                    onMouseEnter={() => setActiveIndex(idx)}
                    onClick={() => addTag(item.value)}
                    className={cn(
                      "flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm transition-colors",
                      isActive
                        ? "bg-neutral-100 text-black dark:bg-[#161616] dark:text-white"
                        : "text-neutral-600 hover:bg-neutral-50 dark:text-neutral-400 dark:hover:bg-[#121212]"
                    )}
                  >
                    <span className="flex items-center gap-2 font-medium">
                      <Plus className="h-3.5 w-3.5 text-neutral-400" />
                      {item.label}
                    </span>
                    {item.category && (
                      <span className="rounded-md border border-neutral-200 px-1.5 py-0.5 font-mono text-[10px] text-neutral-500 dark:border-neutral-800 dark:text-neutral-400">
                        {item.category}
                      </span>
                    )}
                  </button>
                );
              })
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

