            <p className="font-mono text-xs text-neutral-300">
              Hover to move your live pointer • Click to send waves • Type
              cursor chat
            </p>
          </div>
        </div>

        {/* Click Wave Ripple Animations */}
        <AnimatePresence>
          {clicks.map((clk) => (
            <motion.div
              key={clk.id}
              initial={{ scale: 0, opacity: 0.9 }}
              animate={{ scale: 3.5, opacity: 0 }}
