"use client";

import React, { useState, useRef } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { Minus, Plus } from "lucide-react";
import { cn } from "@/lib/utils";

export interface StepperSliderControlProps {
  /** Label for the control */
  label?: string;
  /** Controlled numeric value */
  value?: number;
  /** Initial value for uncontrolled mode. Default: 60 */
  defaultValue?: number;
  /** Minimum value. Default: 0 */
  min?: number;
  /** Maximum value. Default: 100 */
  max?: number;
  /** Step increment for both slider and (− / +) buttons. Default: 5 */
  step?: number;
  /** Optional unit suffix (e.g. "%", "px", "dB"). Default: "%" */
  unit?: string;
  /** Callback fired when value changes */
  onChange?: (value: number) => void;
  /** Disable interactions */
  disabled?: boolean;
  className?: string;
}

export function StepperSliderControl({
  label = "Display Brightness",
  value: controlledValue,
  defaultValue = 65,
  min = 0,
  max = 100,
  step = 5,
  unit = "%",
  onChange,
  disabled = false,
  className,
}: StepperSliderControlProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const trackRef = useRef<HTMLDivElement>(null);
  const isControlled = controlledValue !== undefined;

  const [internalVal, setInternalVal] = useState(defaultValue);
  const [isDragging, setIsDragging] = useState(false);

  const currentVal = isControlled ? controlledValue : internalVal;

  const clampAndSnap = (raw: number) => {
    const snapped = Math.round((raw - min) / step) * step + min;
    return Math.max(min, Math.min(max, Number(snapped.toFixed(4))));
  };

  const updateValue = (next: number) => {
    if (disabled) return;
    const clamped = clampAndSnap(next);
    if (!isControlled) {
      setInternalVal(clamped);
    }
    onChange?.(clamped);
  };

  const pct =
    max > min ? Math.max(0, Math.min(100, ((currentVal - min) / (max - min)) * 100)) : 0;

  const updateFromPointer = (clientX: number) => {
    if (!trackRef.current || disabled) return;
    const rect = trackRef.current.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    const rawValue = min + ratio * (max - min);
    updateValue(rawValue);
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
    updateFromPointer(e.clientX);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDragging || disabled) return;
    updateFromPointer(e.clientX);
  };

  const handlePointerUp = () => {
    setIsDragging(false);
  };

  return (
    <div
      className={cn(
        "w-full max-w-sm rounded-3xl border border-neutral-200 bg-white p-5 shadow-sm dark:border-neutral-800 dark:bg-[#0A0A0A]",
        disabled && "opacity-50",
        className
      )}
    >
      {/* Top Row: Label + Value Readout */}
      <div className="flex items-center justify-between">
        <span className="text-xs font-semibold text-neutral-950 dark:text-white">
          {label}
        </span>
        <span className="font-mono text-sm font-bold tracking-tight text-neutral-950 dark:text-white">
          {currentVal}
          {unit}
        </span>
      </div>

      {/* Thin-Track Slider with Large Round Thumb */}
      <div
        ref={trackRef}
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={currentVal}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onKeyDown={(e) => {
          if (disabled) return;
          if (e.key === "ArrowRight" || e.key === "ArrowUp") {
            e.preventDefault();
            updateValue(currentVal + step);
          } else if (e.key === "ArrowLeft" || e.key === "ArrowDown") {
            e.preventDefault();
            updateValue(currentVal - step);
          } else if (e.key === "Home") {
            e.preventDefault();
            updateValue(min);
          } else if (e.key === "End") {
            e.preventDefault();
            updateValue(max);
          }
        }}
        className="relative my-5 flex h-7 cursor-pointer touch-none select-none items-center focus-visible:outline-none"
      >
        {/* Thin Background Track */}
        <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-neutral-200 dark:bg-neutral-800">
          <motion.div
            animate={{ width: `${pct}%` }}
            transition={
              isDragging || shouldReduceMotion
                ? { duration: 0 }
                : { type: "spring", stiffness: 420, damping: 32 }
            }
            className="h-full rounded-full bg-neutral-900 dark:bg-white"
          />
        </div>

        {/* Large Round Thumb */}
        <motion.div
          animate={{
            left: `calc(${pct}% - 12px)`,
            scale: isDragging && !shouldReduceMotion ? 1.15 : 1,
          }}
          transition={
            isDragging || shouldReduceMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 420, damping: 32 }
          }
          className="pointer-events-none absolute h-6 w-6 rounded-full border-2 border-neutral-900 bg-white shadow-md dark:border-white dark:bg-neutral-950"
        />
      </div>

      {/* Bottom Row: Minimal Stepper (− / +) & Fine-Tune Controls */}
      <div className="flex items-center justify-between border-t border-neutral-100 pt-3.5 dark:border-neutral-900">
        <span className="font-mono text-[11px] text-neutral-400">
          Step: {step}
          {unit}
        </span>

        {/* Apple-Style Segmented Pill Stepper (− | +) */}
        <div className="inline-flex h-9 items-center overflow-hidden rounded-xl border border-neutral-200 bg-neutral-100/80 dark:border-neutral-800 dark:bg-neutral-900">
          <button
            type="button"
            aria-label={`Decrease ${label}`}
            disabled={disabled || currentVal <= min}
            onClick={() => updateValue(currentVal - step)}
            className="flex h-full w-11 items-center justify-center text-neutral-700 transition-colors hover:bg-neutral-200/70 active:scale-95 disabled:cursor-not-allowed disabled:opacity-35 dark:text-neutral-200 dark:hover:bg-neutral-800"
          >
            <Minus className="h-3.5 w-3.5 stroke-[2.2]" />
          </button>

          <span
            aria-hidden="true"
            className="h-4 w-px bg-neutral-300 dark:bg-neutral-700"
          />

          <button
            type="button"
            aria-label={`Increase ${label}`}
            disabled={disabled || currentVal >= max}
            onClick={() => updateValue(currentVal + step)}
            className="flex h-full w-11 items-center justify-center text-neutral-700 transition-colors hover:bg-neutral-200/70 active:scale-95 disabled:cursor-not-allowed disabled:opacity-35 dark:text-neutral-200 dark:hover:bg-neutral-800"
          >
            <Plus className="h-3.5 w-3.5 stroke-[2.2]" />
          </button>
        </div>
      </div>
    </div>
  );
}

export default StepperSliderControl;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useState, useRef } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Layers, Shield, Zap, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

export interface StorySection {
  id: string;
  badge: string;
  title: string;
  description: string;
  metricLabel: string;
  metricValue: string;
}

export interface StickyScrollStoryProps {
  /** Array of storytelling chapters */
  sections?: StorySection[];
  /** Optional header title above the storytelling container */
  heading?: string;
  className?: string;
}

const DEFAULT_SECTIONS: StorySection[] = [
  {
    id: "design",
    badge: "01 · Design System",
    title: "Machined from a single block of tokens.",
    description:
      "Every border, surface, and shadow shares a unified monochrome scale that adapts seamlessly between daylight and OLED dark mode.",
    metricLabel: "Contrast Ratio",
    metricValue: "18.4 : 1 AAA",
  },
  {
    id: "motion",
    badge: "02 · Spring Physics",
    title: "Interruptible motion that respects momentum.",
    description:
      "Unlike fixed-duration CSS curves, spring animations preserve velocity when redirected mid-flight for natural tactile feedback.",
    metricLabel: "Response Latency",
    metricValue: "< 1.2 ms",
  },
  {
    id: "shipping",
    badge: "03 · Zero Lock-In",
    title: "Own every line of code in your repository.",
    description:
      "Install via CLI or copy the TypeScript file directly. No black-box npm wrapper, no CSS conflicts, and full control over markup.",
    metricLabel: "Runtime Overhead",
    metricValue: "0 KB External",
  },
];

export function StickyScrollStory({
  sections = DEFAULT_SECTIONS,
  heading = "Scroll inside the container or click any chapter",
  className,
}: StickyScrollStoryProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const [activeIndex, setActiveIndex] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    const maxScroll = el.scrollHeight - el.clientHeight;
    if (maxScroll <= 0) return;
    const progress = el.scrollTop / maxScroll;
    const idx = Math.min(
      sections.length - 1,
      Math.max(0, Math.round(progress * (sections.length - 1)))
    );
    if (idx !== activeIndex) {
      setActiveIndex(idx);
    }
  };

  const scrollToChapter = (index: number) => {
    setActiveIndex(index);
    const el = scrollContainerRef.current;
    if (!el) return;
    const maxScroll = el.scrollHeight - el.clientHeight;
    const targetTop =
      sections.length > 1 ? (index / (sections.length - 1)) * maxScroll : 0;
    el.scrollTo({ top: targetTop, behavior: "smooth" });
  };

  const activeSection = sections[activeIndex] ?? sections[0];

  const icons = [
    <Layers key="layers" className="h-5 w-5" />,
    <Zap key="zap" className="h-5 w-5" />,
    <Shield key="shield" className="h-5 w-5" />,
    <Sparkles key="sparkles" className="h-5 w-5" />,
  ];

  return (
    <div
      className={cn(
        "w-full max-w-2xl overflow-hidden rounded-3xl border border-neutral-200 bg-white shadow-sm dark:border-neutral-800 dark:bg-[#0A0A0A]",
        className
      )}
    >
      {/* Top Status Bar */}
      <div className="flex items-center justify-between border-b border-neutral-200 bg-neutral-50/70 px-5 py-2.5 dark:border-neutral-800 dark:bg-neutral-900/50">
        <span className="font-mono text-[11px] text-neutral-500 dark:text-neutral-400">
          {heading}
        </span>
        <div className="flex items-center gap-1.5">
          {sections.map((sec, idx) => (
            <button
              key={sec.id}
              type="button"
              aria-label={`Jump to chapter ${idx + 1}`}
              onClick={() => scrollToChapter(idx)}
              className={cn(
                "h-1.5 rounded-full transition-all",
                idx === activeIndex
                  ? "w-5 bg-neutral-900 dark:bg-white"
                  : "w-1.5 bg-neutral-300 hover:bg-neutral-400 dark:bg-neutral-700"
              )}
            />
          ))}
        </div>
      </div>

      {/* Split Scrollable Text + Sticky Synced Media */}
      <div
        ref={scrollContainerRef}
        data-fullscreen-scroll
        onScroll={handleScroll}
        className="grid max-h-[340px] grid-cols-1 gap-6 overflow-y-auto p-6 sm:grid-cols-12"
      >
        {/* Left Scrolling Chapters */}
        <div className="space-y-24 py-6 pb-28 sm:col-span-7">
          {sections.map((section, idx) => {
            const isActive = idx === activeIndex;
            return (
              <div
                key={section.id}
                onClick={() => scrollToChapter(idx)}
                className={cn(
                  "cursor-pointer rounded-2xl p-4 transition-all duration-300",
                  isActive
                    ? "bg-neutral-100/80 opacity-100 dark:bg-neutral-900/80"
                    : "opacity-40 hover:opacity-70"
                )}
              >
                <span className="font-mono text-[11px] font-semibold uppercase tracking-wider text-neutral-500 dark:text-neutral-400">
                  {section.badge}
                </span>
                <h3 className="mt-1.5 text-base font-bold tracking-tight text-neutral-950 dark:text-white sm:text-lg">
                  {section.title}
                </h3>
                <p className="mt-2 text-xs leading-relaxed text-neutral-600 dark:text-neutral-400">
                  {section.description}
                </p>
              </div>
            );
          })}
        </div>

        {/* Right Sticky Media Stage */}
        <div className="sm:col-span-5">
          <div className="sticky top-2 flex h-[240px] flex-col justify-between overflow-hidden rounded-2xl border border-neutral-200 bg-neutral-50 p-5 dark:border-neutral-800 dark:bg-[#111111]">
            <AnimatePresence mode="wait">
              <motion.div
                key={activeSection.id}
                initial={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, y: 14, scale: 0.96 }
                }
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, y: -14, scale: 0.96 }
                }
                transition={{ type: "spring", stiffness: 360, damping: 28 }}
                className="flex h-full flex-col justify-between"
              >
                <div className="flex items-center justify-between">
                  <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-neutral-900 text-white dark:bg-white dark:text-black">
                    {icons[activeIndex % icons.length]}
                  </div>
                  <span className="rounded-full border border-neutral-200 bg-white px-2.5 py-0.5 font-mono text-[10px] font-semibold text-neutral-600 dark:border-neutral-800 dark:bg-neutral-950 dark:text-neutral-300">
                    Step {activeIndex + 1}/{sections.length}
                  </span>
                </div>

                {/* Center Visual Graphic */}
                <div className="my-auto rounded-xl border border-neutral-200/80 bg-white p-3.5 shadow-2xs dark:border-neutral-800 dark:bg-[#0A0A0A]">
                  <div className="font-mono text-[10px] uppercase tracking-wider text-neutral-400">
                    {activeSection.metricLabel}
                  </div>
                  <div className="mt-1 font-mono text-lg font-bold tracking-tight text-neutral-950 dark:text-white">
                    {activeSection.metricValue}
                  </div>
                  <div className="mt-2.5 h-1.5 w-full overflow-hidden rounded-full bg-neutral-100 dark:bg-neutral-900">
                    <motion.div
                      initial={{ width: "20%" }}
                      animate={{
                        width: `${((activeIndex + 1) / sections.length) * 100}%`,
                      }}
                      transition={{ type: "spring", stiffness: 300, damping: 28 }}
                      className="h-full rounded-full bg-neutral-900 dark:bg-white"
                    />
                  </div>
                </div>

                <div className="font-mono text-[10px] text-neutral-400">
                  Synced Sticky Stage
                </div>
              </motion.div>
            </AnimatePresence>
          </div>
        </div>
      </div>
    </div>
  );
}

export default StickyScrollStory;

