            {/* Sliding Underline Tabs */}
            <div className="flex items-center space-x-1" role="tablist">
              {Object.values(SNIPPETS).map((snip) => {
                const isActive = activeLang === snip.id;
                return (
                  <button
                    key={snip.id}
                    onClick={() => setActiveLang(snip.id)}
