          </AnimatePresence>
        </div>

        {/* Interactive Run Console Terminal Output */}
        <AnimatePresence>
          {terminalOpen && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
