  children?: React.ReactNode;
  className?: string;
}

interface Star3D {
  x: number;
  y: number;
  z: number;
  pz: number;
}

export function WarpSpeed({
  speed = 180,
  starCount = 320,
  streakLength = 1.4,
  warp = false,
  center = { x: 0.5, y: 0.5 },
  followCursor = true,
  children,
  className,
}: WarpSpeedProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isWarping, setIsWarping] = useState(warp);
  const vanishingRef = useRef({
    x: center.x,
    y: center.y,
    targetX: center.x,
    targetY: center.y,
  });

  useEffect(() => {
    setIsWarping(warp);
  }, [warp]);

  useEffect(() => {
    vanishingRef.current.targetX = center.x;
    vanishingRef.current.targetY = center.y;
  }, [center.x, center.y]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let rafId: number;
    let width = (canvas.width = canvas.offsetWidth || 600);
    let height = (canvas.height = canvas.offsetHeight || 360);
    const maxDepth = 1000;

    const createStar = (): Star3D => {
      const z = Math.random() * maxDepth + 1;
      return {
        x: (Math.random() - 0.5) * width * 2.2,
        y: (Math.random() - 0.5) * height * 2.2,
        z,
        pz: z,
      };
    };

    const stars: Star3D[] = Array.from({ length: starCount }, createStar);
    let currentVelocity = speed;

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = canvas.offsetWidth || 600;
      height = canvas.height = canvas.offsetHeight || 360;
    };

    window.addEventListener("resize", handleResize);

    let last = performance.now();
    const render = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;

      // Smoothly ramp velocity up or down for warp jump
      const targetVelocity = isWarping ? speed * 5.2 : speed;
      currentVelocity += (targetVelocity - currentVelocity) * 0.08;

      // Smoothly interpolate vanishing point
      vanishingRef.current.x +=
        (vanishingRef.current.targetX - vanishingRef.current.x) * 0.08;
      vanishingRef.current.y +=
        (vanishingRef.current.targetY - vanishingRef.current.y) * 0.08;

      const cx = vanishingRef.current.x * width;
      const cy = vanishingRef.current.y * height;
      const focal = Math.min(width, height) * 0.65;

      ctx.fillStyle = isWarping
        ? "rgba(3, 5, 12, 0.32)"
        : "rgba(3, 5, 12, 0.55)";
      ctx.fillRect(0, 0, width, height);

      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        s.pz = s.z + currentVelocity * dt * streakLength * (isWarping ? 2.8 : 1);
        s.z -= currentVelocity * dt;

        if (s.z <= 2) {
          s.x = (Math.random() - 0.5) * width * 2.2;
          s.y = (Math.random() - 0.5) * height * 2.2;
          s.z = maxDepth;
          s.pz = maxDepth;
          continue;
        }

        // 3D perspective projection: screenX = (x / z) * focal + cx
        const sx = (s.x / s.z) * focal + cx;
        const sy = (s.y / s.z) * focal + cy;
        const px = (s.x / s.pz) * focal + cx;
        const py = (s.y / s.pz) * focal + cy;

        const depthRatio = 1 - s.z / maxDepth;
        const alpha = Math.max(0.08, Math.min(1, depthRatio * 1.2));
        const lineWidth = Math.max(0.6, depthRatio * (isWarping ? 2.8 : 2.0));

        ctx.strokeStyle = isWarping
          ? `rgba(186, 230, 253, ${alpha.toFixed(3)})`
          : `rgba(255, 255, 255, ${alpha.toFixed(3)})`;
        ctx.lineWidth = lineWidth;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(sx, sy);
        ctx.stroke();
      }

      rafId = requestAnimationFrame(render);
    };

    rafId = requestAnimationFrame(render);
    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener("resize", handleResize);
    };
  }, [speed, starCount, streakLength, isWarping]);

  return (
    <div
      data-fullscreen-scroll
      onMouseMove={(e) => {
        if (!followCursor) return;
        const rect = e.currentTarget.getBoundingClientRect();
        vanishingRef.current.targetX = (e.clientX - rect.left) / rect.width;
        vanishingRef.current.targetY = (e.clientY - rect.top) / rect.height;
      }}
      onMouseLeave={() => {
        if (!followCursor) return;
        vanishingRef.current.targetX = center.x;
        vanishingRef.current.targetY = center.y;
      }}
      className={cn(
        "relative flex min-h-[360px] w-full flex-col justify-between overflow-hidden rounded-3xl border border-neutral-800 bg-[#03050C] p-6 text-white shadow-sm",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full"
      />

      <div className="relative z-10 flex flex-1 flex-col justify-between">
        {children ?? (
          <>
            <div className="flex flex-wrap items-center justify-between gap-2">
              <span className="inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-black/40 px-3 py-1 font-mono text-[11px] font-medium text-white backdrop-blur-md">
                <Zap className="h-3.5 w-3.5 text-sky-400" />
                Warp Speed · {isWarping ? "HYPERSPACE" : "SUBLIGHT"}
              </span>

              <button
                type="button"
                onClick={() => setIsWarping((w) => !w)}
                className={cn(
                  "inline-flex items-center gap-1.5 rounded-full border px-3.5 py-1 font-mono text-xs font-semibold transition-all active:scale-95",
                  isWarping
                    ? "border-sky-400 bg-sky-400 text-black shadow-[0_0_20px_rgba(56,189,248,0.6)]"
                    : "border-white/20 bg-white/10 text-white backdrop-blur-md hover:bg-white/20"
                )}
              >
                <Zap className="h-3 w-3" />
                <span>{isWarping ? "Disengage Warp" : "Engage Warp Jump"}</span>
              </button>
            </div>

            <div className="my-auto max-w-md py-8">
              <h3 className="text-2xl font-bold tracking-tight text-white sm:text-3xl">
                3D Hyperspace Projection
              </h3>
              <p className="mt-2 text-xs leading-relaxed text-white/75 sm:text-sm">
                Projects 3D star coordinates via{" "}
                <code className="font-mono text-sky-300">screenX = x / z</code>{" "}
                with cursor-steered vanishing point and velocity streak ramps.
              </p>
            </div>

            <div className="font-mono text-[11px] text-white/50">
              Move cursor to steer vanishing point · Click button to jump
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default WarpSpeed;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useState, useEffect, useMemo, useCallback } from "react";
import { motion, useReducedMotion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";

export type WarpDirection = "forward" | "left" | "right" | "up" | "down";
export type WarpTrigger = "mount" | "viewport" | "hover" | "manual";
export type WarpSplit = "character" | "word" | "line";

export interface WarpTextProps {
  /** The text string to animate through warp speed */
  text?: string;
  /** Direction of the warp acceleration. Default: "forward" */
  direction?: WarpDirection;
  /** Speed multiplier for acceleration. Default: 1 */
  speed?: number;
  /** Base duration of the warp sequence in seconds. Default: 1.1 */
  duration?: number;
  /** Delay before animation starts in seconds. Default: 0 */
  delay?: number;
  /** Whether to apply directional motion blur. Default: true */
  blur?: boolean;
  /** Whether to render photonic bloom and glow highlights. Default: true */
  glow?: boolean;
  /** Whether to render velocity motion trail echoes. Default: true */
  trail?: boolean;
  /** Whether to repeat the animation continuously in a loop. Default: false */
  loop?: boolean;
  /** Animation trigger condition. Default: "mount" */
  trigger?: WarpTrigger;
  /** How the text is partitioned for animation stagger. Default: "character" */
  split?: WarpSplit;
  /** Optional custom glow accent color. Defaults to futuristic cyan/blue */
  glowColor?: string;
  /** Custom CSS classes for the container */
  className?: string;
  /** Whether to render the full interactive showcase demo playground. Default: false */
  demoMode?: boolean;
  /** Callback fired when the warp sequence finishes */
  onAnimationComplete?: () => void;
}

export function WarpText({
  text = "WARP SPEED",
  direction = "forward",
  speed = 1,
  duration = 1.1,
  delay = 0,
  blur = true,
  glow = true,
  trail = true,
  loop = false,
  trigger = "mount",
  split = "character",
  glowColor = "rgba(56, 189, 248, 0.75)",
  className,
  demoMode = false,
  onAnimationComplete,
}: WarpTextProps) {
  if (demoMode) {
    return <WarpTextDemo className={className} />;
  }

  const shouldReduceMotion = useReducedMotion() ?? false;
  const [animationKey, setAnimationKey] = useState(0);
  const [isHovered, setIsHovered] = useState(false);

  // Compute calculated duration based on speed
  const actualDuration = Math.max(0.3, duration / Math.max(0.2, speed));
  const staggerDuration = (0.025 / Math.max(0.5, speed));

  const triggerAnimation = useCallback(() => {
    setAnimationKey((prev) => prev + 1);
  }, []);

  // Split text into tokens based on chosen granularity
  const tokens = useMemo(() => {
    if (!text) return [];

    if (split === "line") {
      return text.split("\n").map((line, idx) => ({
        id: `line-${idx}`,
        content: line,
        isSpace: false,
      }));
    }

    if (split === "word") {
      return text.split(" ").map((word, idx) => ({
        id: `word-${idx}`,
        content: word,
        isSpace: false,
      }));
    }

    // Default: Character split with preserved word boundaries
    const words = text.split(" ");
    const charList: Array<{ id: string; content: string; isSpace: boolean }> = [];

    words.forEach((word, wIdx) => {
      const chars = word.split("");
      chars.forEach((char, cIdx) => {
        charList.push({
          id: `char-${wIdx}-${cIdx}`,
          content: char,
          isSpace: false,
        });
      });

      if (wIdx < words.length - 1) {
        charList.push({
          id: `space-${wIdx}`,
          content: "\u00A0",
          isSpace: true,
        });
      }
    });

    return charList;
  }, [text, split]);

  // Motion variants based on direction and physics
  const getVariants = (): {
    container: Variants;
    item: Variants;
    trail1: Variants;
    trail2: Variants;
  } => {
    if (shouldReduceMotion) {
      return {
        container: {
          hidden: { opacity: 0 },
          visible: {
            opacity: 1,
            transition: { duration: actualDuration, delay },
          },
        },
        item: {
          hidden: { opacity: 0 },
          visible: { opacity: 1 },
        },
        trail1: { hidden: { opacity: 0 }, visible: { opacity: 0 } },
        trail2: { hidden: { opacity: 0 }, visible: { opacity: 0 } },
      };
    }

    // Directional offsets and stretches
    let initialX = 0;
    let initialY = 0;
    let initialScale = 1;
    let initialScaleX = 1;
    let initialScaleY = 1;
    let blurValue = blur ? "16px" : "0px";

    switch (direction) {
      case "left":
        initialX = 160;
        initialScaleX = 2.4;
        initialScaleY = 0.85;
        break;
      case "right":
        initialX = -160;
        initialScaleX = 2.4;
        initialScaleY = 0.85;
        break;
      case "up":
        initialY = 120;
        initialScaleY = 2.2;
        initialScaleX = 0.9;
        break;
      case "down":
        initialY = -120;
        initialScaleY = 2.2;
        initialScaleX = 0.9;
        break;
      case "forward":
      default:
        initialScale = 0.12;
        blurValue = blur ? "24px" : "0px";
        break;
    }

    const containerVariants: Variants = {
      hidden: {},
      visible: {
        transition: {
          staggerChildren: staggerDuration,
          delayChildren: delay,
        },
      },
    };

    const itemVariants: Variants = {
      hidden: {
        opacity: 0,
        x: initialX,
        y: initialY,
        scale: initialScale,
        scaleX: initialScaleX,
        scaleY: initialScaleY,
        filter: `blur(${blurValue})`,
      },
      visible: {
        opacity: 1,
        x: 0,
        y: 0,
        scale: 1,
        scaleX: 1,
        scaleY: 1,
        filter: "blur(0px)",
        transition: {
          duration: actualDuration,
          ease: [0.16, 1, 0.3, 1], // Cinematic rapid decel curve
          repeat: loop ? Infinity : 0,
          repeatDelay: loop ? 1.6 : 0,
          repeatType: "loop",
        },
      },
    };

    const trail1Variants: Variants = {
      hidden: {
        opacity: 0,
        x: initialX * 1.35,
        y: initialY * 1.35,
        scale: initialScale * 1.25,
        scaleX: initialScaleX * 1.2,
        scaleY: initialScaleY * 1.2,
        filter: blur ? "blur(18px)" : "blur(0px)",
      },
      visible: {
        opacity: [0, 0.45, 0],
        x: 0,
        y: 0,
        scale: 1,
        scaleX: 1,
        scaleY: 1,
        filter: "blur(0px)",
        transition: {
          duration: actualDuration * 0.85,
          ease: "easeOut",
          repeat: loop ? Infinity : 0,
          repeatDelay: loop ? 1.6 : 0,
        },
      },
    };

    const trail2Variants: Variants = {
      hidden: {
        opacity: 0,
        x: initialX * 1.7,
        y: initialY * 1.7,
        scale: initialScale * 1.5,
        scaleX: initialScaleX * 1.4,
        scaleY: initialScaleY * 1.4,
        filter: blur ? "blur(26px)" : "blur(0px)",
      },
      visible: {
        opacity: [0, 0.25, 0],
        x: 0,
        y: 0,
        scale: 1,
        scaleX: 1,
        scaleY: 1,
        filter: "blur(0px)",
        transition: {
          duration: actualDuration * 0.95,
          ease: "easeOut",
          repeat: loop ? Infinity : 0,
          repeatDelay: loop ? 1.6 : 0,
        },
      },
    };

    return {
      container: containerVariants,
      item: itemVariants,
      trail1: trail1Variants,
      trail2: trail2Variants,
    };
  };

  const { container, item, trail1, trail2 } = getVariants();

  // Handle hover trigger
  const handleMouseEnter = () => {
    setIsHovered(true);
    if (trigger === "hover") {
      triggerAnimation();
    }
  };

  return (
    <div
      className={cn(
        "relative inline-flex items-center justify-center select-none font-bold tracking-tight",
        trigger === "hover" && "cursor-pointer",
        className
      )}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={() => setIsHovered(false)}
      style={
        glow
          ? ({
              textShadow: `0 0 20px ${glowColor}, 0 0 40px ${glowColor.replace(/[\d.]+\)$/, "0.35)")}`,
            } as React.CSSProperties)
          : undefined
      }
    >
      {/* Screen reader full accessibility string */}
      <span className="sr-only">{text}</span>

      {/* Primary Animated Tokens */}
      <motion.div
        key={animationKey}
        variants={container}
        initial="hidden"
        animate={trigger === "viewport" ? undefined : "visible"}
        whileInView={trigger === "viewport" ? "visible" : undefined}
        viewport={trigger === "viewport" ? { once: !loop } : undefined}
        onAnimationComplete={onAnimationComplete}
        aria-hidden="true"
        className="flex flex-wrap items-center justify-center leading-none"
      >
        {tokens.map((token) => (
          <span
            key={token.id}
            className={cn(
              "relative inline-block",
              split === "word" && "mr-[0.28em] last:mr-0"
            )}
          >
            {/* Trailing photonic echoes */}
            {trail && !shouldReduceMotion && (
              <>
                <motion.span
                  variants={trail1}
                  className="pointer-events-none absolute inset-0 text-cyan-400/60 dark:text-cyan-300/70 select-none mix-blend-screen"
                  style={{ willChange: "transform, opacity, filter" }}
                >
                  {token.content}
                </motion.span>
                <motion.span
                  variants={trail2}
                  className="pointer-events-none absolute inset-0 text-violet-400/40 dark:text-violet-300/50 select-none mix-blend-screen"
                  style={{ willChange: "transform, opacity, filter" }}
                >
                  {token.content}
                </motion.span>
              </>
            )}

            {/* Main Token */}
            <motion.span
              variants={item}
              className="inline-block transform-gpu"
              style={{ willChange: "transform, opacity, filter" }}
            >
              {token.content}
            </motion.span>
          </span>
        ))}
      </motion.div>
    </div>
  );
}

/**
 * Interactive Demo Playground for documentation and registry previews.
