"use client";

import React, { useEffect, useRef, useState } from "react";
import { Radio, CloudRain, MousePointerClick } from "lucide-react";
import { cn } from "@/lib/utils";

export interface WaterRipplesProps {
  /** Wave energy retention factor per frame (0.90 to 0.995). Default: 0.97 */
  damping?: number;
  /** Maximum expansion radius of spawned concentric ripple rings in px. Default: 140 */
  rippleRadius?: number;
  /** Automatically spawn periodic rain/ambient droplets across the surface. Default: true */
  ambientDrops?: boolean;
  /** Primary specular caustic highlight hex color. Default: "#38BDF8" */
  color?: string;
  /** Spawn ripples on pointer move and click. Default: true */
  interactive?: boolean;
  /** Optional foreground content */
  children?: React.ReactNode;
  className?: string;
}

function hexToRgb(hex: string): [number, number, number] {
  const clean = hex.replace("#", "").trim();
  if (clean.length === 3) {
    return [
      parseInt(clean[0] + clean[0], 16) || 56,
      parseInt(clean[1] + clean[1], 16) || 189,
      parseInt(clean[2] + clean[2], 16) || 248,
    ];
  }
  const num = parseInt(clean, 16);
  if (Number.isNaN(num)) return [56, 189, 248];
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

const RIPPLE_PRESETS = [
  { name: "Lagoon Pool", color: "#38BDF8", damping: 0.975, radius: 140 },
  { name: "Jade Sanctuary", color: "#34D399", damping: 0.982, radius: 175 },
  { name: "Sapphire Basin", color: "#818CF8", damping: 0.962, radius: 120 },
];

export function WaterRipples({
  damping = 0.97,
  rippleRadius = 140,
  ambientDrops = true,
  color = "#38BDF8",
  interactive = true,
  children,
  className,
}: WaterRipplesProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [liveDamping, setLiveDamping] = useState(damping);
  const [liveRadius, setLiveRadius] = useState(rippleRadius);
  const [liveAmbient, setLiveAmbient] = useState(ambientDrops);
  const [liveColor, setLiveColor] = useState(color);
  const [dropCounter, setDropCounter] = useState(0);

  useEffect(() => setLiveDamping(damping), [damping]);
  useEffect(() => setLiveRadius(rippleRadius), [rippleRadius]);
  useEffect(() => setLiveAmbient(ambientDrops), [ambientDrops]);
  useEffect(() => setLiveColor(color), [color]);

  const paramsRef = useRef({
    damping: liveDamping,
    radius: liveRadius,
    ambient: liveAmbient,
    color: liveColor,
  });

  useEffect(() => {
    paramsRef.current = {
      damping: liveDamping,
      radius: liveRadius,
      ambient: liveAmbient,
      color: liveColor,
    };
  }, [liveDamping, liveRadius, liveAmbient, liveColor]);

  // Imperative disturb callback ref so pointer handlers trigger ripples without re-mounting
  const disturbRef = useRef<
    (normX: number, normY: number, strength: number) => void
  >(() => {});

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let simW = 280;
    let simH = 180;
    let bufPrev = new Float32Array(simW * simH);
    let bufCurr = new Float32Array(simW * simH);
    // Precomputed procedural submerged mosaic/pebble & static caustic texture buffer
    let bedTex = new Float32Array(simW * simH);

    const offscreen = document.createElement("canvas");
    offscreen.width = simW;
    offscreen.height = simH;
    const offCtx = offscreen.getContext("2d");
    let imgData = offCtx ? offCtx.createImageData(simW, simH) : null;

    const buildSubmergedBed = (w: number, h: number) => {
      bedTex = new Float32Array(w * h);
      for (let y = 0; y < h; y++) {
        const ny = y / h;
        for (let x = 0; x < w; x++) {
          const nx = x / w;
          // Subtle submerged stone tile grid + organic pebble/sand harmonic texture
          const tileX = Math.abs(Math.sin(nx * Math.PI * 14));
          const tileY = Math.abs(Math.sin(ny * Math.PI * 9));
          const grout = Math.pow(Math.min(tileX, tileY), 0.18);

          const pebble =
            0.5 +
            0.25 * Math.sin(x * 0.23 + Math.cos(y * 0.19) * 2.5) +
            0.25 * Math.cos(y * 0.27 - Math.sin(x * 0.21) * 2.5);

          bedTex[y * w + x] = grout * (0.72 + 0.28 * pebble);
        }
      }
    };

    let viewW = 1;
    let viewH = 1;
    let dpr = 1;

    const resize = () => {
      const rect = container.getBoundingClientRect();
      viewW = Math.max(1, rect.width);
      viewH = Math.max(1, rect.height);
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(viewW * dpr);
      canvas.height = Math.floor(viewH * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      // 0.45x simulation grid resolution for silky 60fps per-pixel 3D normal shading
      const nextSimW = Math.max(160, Math.min(340, Math.floor(viewW * 0.42)));
      const nextSimH = Math.max(110, Math.min(230, Math.floor(viewH * 0.42)));
      if (nextSimW !== simW || nextSimH !== simH || bedTex.length === 0) {
        simW = nextSimW;
        simH = nextSimH;
        bufPrev = new Float32Array(simW * simH);
        bufCurr = new Float32Array(simW * simH);
        buildSubmergedBed(simW, simH);
        offscreen.width = simW;
        offscreen.height = simH;
        imgData = offCtx ? offCtx.createImageData(simW, simH) : null;
      }
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);

    const triggerRipple = (normX: number, normY: number, strength: number) => {
      const gx = Math.floor(normX * simW);
      const gy = Math.floor(normY * simH);
      const rad = Math.max(
        3,
        Math.min(12, Math.round((paramsRef.current.radius / 140) * 6))
      );

      for (let dy = -rad; dy <= rad; dy++) {
        const y = gy + dy;
        if (y <= 2 || y >= simH - 2) continue;
        for (let dx = -rad; dx <= rad; dx++) {
          const x = gx + dx;
          if (x <= 2 || x >= simW - 2) continue;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist <= rad) {
            // Smooth raised ring profile so each drop launches a realistic capillary wave packet
            const phase = (dist / rad) * Math.PI;
            const profile = Math.cos(phase);
            bufPrev[y * simW + x] -= strength * profile;
          }
        }
      }
    };

    disturbRef.current = triggerRipple;

    // Seed initial welcoming droplets
    triggerRipple(0.35, 0.45, 220);
    triggerRipple(0.66, 0.54, 190);

    let rafId = 0;
    let frame = 0;

    // Normalized 3D directional light vector L = normalize(-0.45, -0.55, 0.70)
    // and Halfway vector H = normalize(L + V) where V = (0, 0, 1)
    const lx = -0.45;
    const ly = -0.55;
    const lz = 0.703;
    const hLen = Math.hypot(lx, ly, lz + 1.0);
    const hx = lx / hLen;
    const hy = ly / hLen;
    const hz = (lz + 1.0) / hLen;

    const render = () => {
      frame++;
      const {
        damping: curDamping,
        ambient: curAmbient,
        color: curColor,
      } = paramsRef.current;

      const [tintR, tintG, tintB] = hexToRgb(curColor);
      const damp = Math.max(0.9, Math.min(0.994, curDamping));

      // Periodic ambient rain droplets
      if (curAmbient && frame % 24 === 0) {
        triggerRipple(
          0.1 + Math.random() * 0.8,
          0.12 + Math.random() * 0.76,
          140 + Math.random() * 120
        );
      }

      // 1. Step 2D Wave Equation with 8-neighbor isotropic Laplacian kernel for circular waves
      for (let y = 1; y < simH - 1; y++) {
        const row = y * simW;
        for (let x = 1; x < simW - 1; x++) {
          const idx = row + x;
          const cardinal =
            bufPrev[idx - 1] +
            bufPrev[idx + 1] +
            bufPrev[idx - simW] +
            bufPrev[idx + simW];
          const diagonal =
            bufPrev[idx - simW - 1] +
            bufPrev[idx - simW + 1] +
            bufPrev[idx + simW - 1] +
            bufPrev[idx + simW + 1];

          const avg = cardinal * 0.4 + diagonal * 0.1;
          bufCurr[idx] = (avg - bufCurr[idx]) * damp;
        }
      }

      // 2. Per-pixel 3D Surface Normal Reconstruction, Snell Refraction, Caustic Focusing & Blinn-Phong Specular
      if (offCtx && imgData) {
        const data = imgData.data;
        const timeShift = frame * 0.025;

        for (let y = 1; y < simH - 1; y++) {
          const row = y * simW;
          const vNorm = y / simH;

          for (let x = 1; x < simW - 1; x++) {
            const idx = row + x;

            // Central-difference 2D height-field gradient (dh/dx, dh/dy)
            const dhdx = (bufCurr[idx + 1] - bufCurr[idx - 1]) * 0.032;
            const dhdy = (bufCurr[idx + simW] - bufCurr[idx - simW]) * 0.032;

            // 3D Surface Normal N = normalize(-dhdx, -dhdy, 1.0)
            const invLen = 1.0 / Math.sqrt(dhdx * dhdx + dhdy * dhdy + 1.0);
            const nx = -dhdx * invLen;
            const ny = -dhdy * invLen;
            const nz = invLen;

            // Refracted floor lookup coordinates shifted by surface normal
            const refX = Math.max(
              0,
              Math.min(simW - 1, Math.round(x + nx * 26))
            );
            const refY = Math.max(
              0,
              Math.min(simH - 1, Math.round(y + ny * 26))
            );
            const floorPattern = bedTex[refY * simW + refX];

            // Ambient refracted caustic wave network on the pool floor
            const cx = refX * 0.11 + timeShift;
            const cy = refY * 0.11 - timeShift * 0.7;
            const ambientCaustic = Math.pow(
              0.5 + 0.5 * Math.sin(cx + Math.cos(cy * 1.3)) * Math.cos(cy - Math.sin(cx * 1.2)),
              3.0
            );

            // Wave curvature convergence (Laplacian) creates bright caustic focal rings on the bed
            const curvature = Math.max(
              0,
              bufCurr[idx] * 2.0 -
                (bufCurr[idx - 1] + bufCurr[idx + 1]) * 0.5
            );
            const rippleCaustic = Math.min(1.4, curvature * 0.018);

            // Schlick Fresnel reflection factor: grazing angles reflect more bright sky light
            const fresnel = Math.pow(1.0 - nz, 3.0);

            // Diffuse lighting + sharp Blinn-Phong specular highlight pow(max(dot(N, H), 0.0), 80.0)
            const ndotl = Math.max(0.0, nx * lx + ny * ly + nz * lz);
            const ndoth = Math.max(0.0, nx * hx + ny * hy + nz * hz);
            const specular = Math.pow(ndoth, 80.0) * 1.85 + Math.pow(ndoth, 18.0) * 0.35;

            // Combine deep water absorption + refracted floor + caustics + Fresnel sky + specular glint
            const depthShade = 0.42 + 0.58 * (1.0 - vNorm * 0.45);
            const floorLight =
              floorPattern * depthShade * (0.55 + 0.45 * ndotl) +
              ambientCaustic * 0.24 +
              rippleCaustic * 0.55;

            const rOut =
              4 +
              floorLight * tintR * 0.78 +
              fresnel * 145 +
              specular * 255;
            const gOut =
              14 +
              floorLight * tintG * 0.92 +
              fresnel * 215 +
              specular * 252;
            const bOut =
              30 +
              floorLight * tintB * 1.05 +
              fresnel * 255 +
              specular * 255;

            const p = idx * 4;
            data[p] = rOut > 255 ? 255 : rOut < 0 ? 0 : rOut;
            data[p + 1] = gOut > 255 ? 255 : gOut < 0 ? 0 : gOut;
            data[p + 2] = bOut > 255 ? 255 : bOut < 0 ? 0 : bOut;
            data[p + 3] = 255;
          }
        }

        offCtx.putImageData(imgData, 0, 0);

        // Upscale smoothly onto full-resolution display canvas
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(offscreen, 0, 0, viewW, viewH);
      }

      // Swap wave equation buffers
      const temp = bufPrev;
      bufPrev = bufCurr;
      bufCurr = temp;

      rafId = requestAnimationFrame(render);
    };

    rafId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(rafId);
      ro.disconnect();
    };
  }, []);

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const nx = (e.clientX - rect.left) / Math.max(1, rect.width);
    const ny = (e.clientY - rect.top) / Math.max(1, rect.height);
    disturbRef.current(nx, ny, 95);
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const nx = (e.clientX - rect.left) / Math.max(1, rect.width);
    const ny = (e.clientY - rect.top) / Math.max(1, rect.height);
    disturbRef.current(nx, ny, 280);
    setDropCounter((c) => c + 1);
  };

  return (
    <div
      ref={containerRef}
      data-fullscreen-scroll
      onPointerMove={handlePointerMove}
      onPointerDown={handlePointerDown}
      className={cn(
        "relative flex min-h-[520px] w-full flex-col justify-between overflow-hidden rounded-2xl border border-white/10 bg-[#030A18] p-6 text-white shadow-2xl select-none",
        interactive && "cursor-crosshair",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full"
      />

      {children && (
        <div className="relative z-10 flex min-h-[520px] w-full flex-col">
          {children}
        </div>
      )}
    </div>
  );
}

export default WaterRipples;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Droplets, Sparkles, Wind } from "lucide-react";
import { cn } from "@/lib/utils";

export interface WaterfallProps {
  /** Water velocity multiplier (0.3 to 2.5). Default: 1.0 */
  flow?: number;
  /** Plunge pool volumetric mist intensity (0 to 1). Default: 0.75 */
  mistAmount?: number;
  /** Primary water tint hex color. Default: "#38BDF8" */
  color?: string;
  /** Width of the waterfall curtain relative to container (0.3 to 1.0). Default: 0.75 */
  curtainWidth?: number;
  /** Upward-bouncing splash droplet density/energy. Default: 1.0 */
  splashIntensity?: number;
  /** Optional foreground content */
  children?: React.ReactNode;
  className?: string;
}

interface WaterRibbon {
  xNorm: number; // -0.5 to 0.5 within curtain
  y: number;
  width: number;
  baseSpeed: number;
  opacity: number;
  layer: 0 | 1 | 2; // 0 = deep subsurface sheet, 1 = turbulent mid-ribbon, 2 = aerated whitewater jet
  phase: number;
  freq: number;
  chuteIndex: number;
}

interface SplashDrop {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  alpha: number;
  life: number;
  maxLife: number;
}

interface MistBank {
  xNorm: number;
  yOffset: number;
  radius: number;
  phase: number;
  speed: number;
  risePhase: number;
}

interface PoolRipple {
  xNorm: number;
  yOffset: number;
  rx: number;
  ry: number;
  maxRx: number;
  alpha: number;
  speed: number;
}

interface CliffLedge {
  side: "left" | "right" | "center";
  yNorm: number;
  xNorm: number;
  wNorm: number;
  hNorm: number;
  shade: number;
  points: Array<{ dx: number; dy: number }>;
}

function hexToRgb(hex: string): [number, number, number] {
  const clean = hex.replace("#", "").trim();
  if (clean.length === 3) {
    return [
      parseInt(clean[0] + clean[0], 16) || 56,
      parseInt(clean[1] + clean[1], 16) || 189,
      parseInt(clean[2] + clean[2], 16) || 248,
    ];
  }
  const num = parseInt(clean, 16);
  if (Number.isNaN(num)) return [56, 189, 248];
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

const PRESETS = [
  { name: "Skógafoss", color: "#38BDF8", flow: 1.0, mist: 0.78, curtain: 0.72 },
  { name: "Emerald Gorge", color: "#2DD4BF", flow: 1.35, mist: 0.9, curtain: 0.85 },
  { name: "Glacial Melt", color: "#60A5FA", flow: 0.85, mist: 0.65, curtain: 0.58 },
];

export function Waterfall({
  flow = 1.0,
  mistAmount = 0.75,
  color = "#38BDF8",
  curtainWidth = 0.75,
  splashIntensity = 1.0,
  children,
  className,
}: WaterfallProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [liveFlow, setLiveFlow] = useState(flow);
  const [liveMist, setLiveMist] = useState(mistAmount);
  const [liveColor, setLiveColor] = useState(color);
  const [liveCurtain, setLiveCurtain] = useState(curtainWidth);

  useEffect(() => setLiveFlow(flow), [flow]);
  useEffect(() => setLiveMist(mistAmount), [mistAmount]);
  useEffect(() => setLiveColor(color), [color]);
  useEffect(() => setLiveCurtain(curtainWidth), [curtainWidth]);

  const paramsRef = useRef({
    flow: liveFlow,
    mist: liveMist,
    color: liveColor,
    curtain: liveCurtain,
    splash: splashIntensity,
  });

  useEffect(() => {
    paramsRef.current = {
      flow: liveFlow,
      mist: liveMist,
      color: liveColor,
      curtain: liveCurtain,
      splash: splashIntensity,
    };
  }, [liveFlow, liveMist, liveColor, liveCurtain, splashIntensity]);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let width = 0;
    let height = 0;
    let dpr = 1;
    let rafId = 0;

    const RIBBON_COUNT = 290;
    const ribbons: WaterRibbon[] = [];
    const drops: SplashDrop[] = [];
    const mistBanks: MistBank[] = [];
    const poolRipples: PoolRipple[] = [];
    const cliffLedges: CliffLedge[] = [];

    // 7 natural rock chutes across the crest lip so water groups into organic streams
    const chuteCenters = [-0.43, -0.29, -0.14, 0.0, 0.15, 0.3, 0.44];

    const initScene = () => {
      ribbons.length = 0;
      for (let i = 0; i < RIBBON_COUNT; i++) {
        const layerRand = Math.random();
        const layer: 0 | 1 | 2 = layerRand < 0.32 ? 0 : layerRand < 0.76 ? 1 : 2;
        const chuteIdx = Math.floor(Math.random() * chuteCenters.length);
        const chuteSpread = layer === 0 ? 0.14 : layer === 1 ? 0.095 : 0.065;
        const xNorm = Math.max(
          -0.49,
          Math.min(
            0.49,
            chuteCenters[chuteIdx] + (Math.random() - 0.5) * 2 * chuteSpread
          )
        );

        ribbons.push({
          xNorm,
          y: Math.random(), // normalized 0 (crest) to 1 (plunge)
          width:
            layer === 0
              ? 14 + Math.random() * 20
              : layer === 1
                ? 4.5 + Math.random() * 8
                : 1.5 + Math.random() * 3.2,
          baseSpeed:
            layer === 0
              ? 0.0055 + Math.random() * 0.003
              : layer === 1
                ? 0.008 + Math.random() * 0.0045
                : 0.011 + Math.random() * 0.006,
          opacity:
            layer === 0
              ? 0.16 + Math.random() * 0.14
              : layer === 1
                ? 0.28 + Math.random() * 0.26
                : 0.55 + Math.random() * 0.4,
          layer,
          phase: Math.random() * Math.PI * 2,
          freq: 2.5 + Math.random() * 4.5,
          chuteIndex: chuteIdx,
        });
      }

      mistBanks.length = 0;
      for (let i = 0; i < 24; i++) {
        mistBanks.push({
          xNorm: (Math.random() - 0.5) * 1.25,
          yOffset: (Math.random() - 0.5) * 44,
          radius: 65 + Math.random() * 110,
          phase: Math.random() * Math.PI * 2,
          speed: 0.5 + Math.random() * 0.85,
          risePhase: Math.random() * Math.PI * 2,
        });
      }

      poolRipples.length = 0;
      for (let i = 0; i < 18; i++) {
        const maxRx = 55 + Math.random() * 140;
        poolRipples.push({
          xNorm: (Math.random() - 0.5) * 0.95,
          yOffset: 6 + Math.random() * 68,
          rx: Math.random() * maxRx,
          ry: 3 + Math.random() * 8,
          maxRx,
          alpha: 0.22 + Math.random() * 0.3,
          speed: 0.65 + Math.random() * 0.85,
        });
      }

      // Generate craggy wet basalt rock strata flanking & behind the cascade
      cliffLedges.length = 0;
      for (let row = 0; row < 11; row++) {
        const yNorm = 0.06 + (row / 10) * 0.72;
        for (const side of ["left", "right", "center"] as const) {
          const polyPts: Array<{ dx: number; dy: number }> = [];
          const segs = 7;
          for (let s = 0; s <= segs; s++) {
            const t = s / segs;
            polyPts.push({
              dx: t,
              dy: (Math.sin(row * 3.1 + s * 1.9) * 0.5 + (Math.random() - 0.5) * 0.5) * 0.04,
            });
          }
          cliffLedges.push({
            side,
            yNorm,
            xNorm:
              side === "left"
                ? 0
                : side === "right"
                  ? 0.68 + (row % 3) * 0.03
                  : 0.22 + (row % 2) * 0.08,
            wNorm:
              side === "center"
                ? 0.52
                : 0.28 + Math.sin(row * 1.7) * 0.06,
            hNorm: 0.09 + (row % 3) * 0.025,
            shade: 0.65 + (row % 4) * 0.12,
            points: polyPts,
          });
        }
      }
    };

    const resize = () => {
      const rect = container.getBoundingClientRect();
      width = Math.max(1, rect.width);
      height = Math.max(1, rect.height);
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      if (ribbons.length === 0) initScene();
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);

    let time = 0;

    const render = () => {
      const {
        flow: curFlow,
        mist: curMist,
        color: curColor,
        curtain: curCurtain,
        splash: curSplash,
      } = paramsRef.current;

      time += 0.016 * curFlow;
      const [r, g, b] = hexToRgb(curColor);
      const clampCurtain = Math.max(0.3, Math.min(1.0, curCurtain));
      const cWidth = width * clampCurtain;
      const centerX = width * 0.5;
      const crestY = height * 0.09;
      const plungeY = height * 0.79;
      const fallHeight = plungeY - crestY;

      // 1. Atmospheric misty gorge sky & deep canyon backdrop
      const skyGrad = ctx.createLinearGradient(0, 0, 0, height);
      skyGrad.addColorStop(0, "#050D1A");
      skyGrad.addColorStop(0.12, "#09192E");
      skyGrad.addColorStop(0.75, "#040B17");
      skyGrad.addColorStop(1, "#02060D");
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, width, height);

      // Top atmospheric zenith glow catching the crest of the waterfall
      const crestSunGlow = ctx.createRadialGradient(
        centerX,
        crestY,
        10,
        centerX,
        crestY + fallHeight * 0.25,
        cWidth * 0.75
      );
      crestSunGlow.addColorStop(0, `rgba(${Math.min(255, r + 80)}, ${Math.min(255, g + 65)}, 255, 0.26)`);
      crestSunGlow.addColorStop(0.45, `rgba(${r}, ${g}, ${b}, 0.1)`);
      crestSunGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
      ctx.fillStyle = crestSunGlow;
      ctx.fillRect(0, 0, width, height);

      // 2. Shadowed wet basalt cliff rock strata flanking & behind the waterfall
      for (let i = 0; i < cliffLedges.length; i++) {
        const ledge = cliffLedges[i];
        const ly = ledge.yNorm * height;
        const lh = ledge.hNorm * height;
        let lx = ledge.xNorm * width;
        let lw = ledge.wNorm * width;

        if (ledge.side === "left") {
          lw = Math.max(width * 0.16, centerX - cWidth * 0.46 + Math.sin(i * 2.1) * 22);
          lx = 0;
        } else if (ledge.side === "right") {
          const rightStart = Math.min(
            width * 0.84,
            centerX + cWidth * 0.46 - Math.cos(i * 1.9) * 22
          );
          lx = rightStart;
          lw = width - rightStart;
        }

        ctx.beginPath();
        ctx.moveTo(lx, ly + lh);
        for (let p = 0; p < ledge.points.length; p++) {
          const pt = ledge.points[p];
          ctx.lineTo(lx + pt.dx * lw, ly + pt.dy * height);
        }
        ctx.lineTo(lx + lw, ly + lh);
        ctx.closePath();

        const rockGrad = ctx.createLinearGradient(0, ly, 0, ly + lh);
        const br = Math.round(12 * ledge.shade);
        const bg = Math.round(22 * ledge.shade);
        const bb = Math.round(36 * ledge.shade);
        rockGrad.addColorStop(0, `rgb(${br + 10}, ${bg + 16}, ${bb + 24})`);
        rockGrad.addColorStop(0.25, `rgb(${br}, ${bg}, ${bb})`);
        rockGrad.addColorStop(1, "#030710");
        ctx.fillStyle = rockGrad;
        ctx.fill();

        // Wet basalt specular sheen on top rock ridge catching mist light
        if (ledge.side !== "center") {
          ctx.beginPath();
          for (let p = 0; p < ledge.points.length; p++) {
            const pt = ledge.points[p];
            if (p === 0) ctx.moveTo(lx + pt.dx * lw, ly + pt.dy * height);
            else ctx.lineTo(lx + pt.dx * lw, ly + pt.dy * height);
          }
          ctx.strokeStyle = `rgba(${Math.min(255, r + 50)}, ${Math.min(255, g + 50)}, 255, 0.14)`;
          ctx.lineWidth = 1.4;
          ctx.stroke();
        }
      }

      // Upper river feeding into the waterfall lip
      const riverGrad = ctx.createLinearGradient(0, 0, 0, crestY + 12);
      riverGrad.addColorStop(0, "#041022");
      riverGrad.addColorStop(0.7, `rgba(${Math.floor(r * 0.45)}, ${Math.floor(g * 0.6)}, ${Math.floor(b * 0.75)}, 0.65)`);
      riverGrad.addColorStop(1, `rgba(225, 248, 255, 0.85)`);
      ctx.fillStyle = riverGrad;
      ctx.fillRect(centerX - cWidth * 0.5, 0, cWidth, crestY + 4);

      // 3. Multi-layered turbulent water ribbons accelerating under gravity v = sqrt(2 * g * y)
      ctx.save();
      ctx.globalCompositeOperation = "lighter";

      for (let i = 0; i < ribbons.length; i++) {
        const rb = ribbons[i];
        // Physical gravitational acceleration: velocity increases with square root of fall distance
        const gravityFactor = Math.sqrt(0.18 + Math.max(0, rb.y) * 1.95);
        rb.y += rb.baseSpeed * curFlow * gravityFactor;

        // Multi-frequency FBM/sine horizontal turbulence as water breaks into chutes
        const yPos = crestY + rb.y * fallHeight;
        const turb =
          Math.sin(rb.y * rb.freq + time * 3.2 + rb.phase) *
            (rb.layer === 0 ? 5.5 : 2.8) +
          Math.cos(rb.y * (rb.freq * 2.1) - time * 4.8 + rb.chuteIndex) * 1.6;

        // Slight inward vena-contracta narrowing mid-fall, then fanning out at plunge base
        const fanFactor = 1.0 - Math.sin(rb.y * Math.PI) * 0.04 + rb.y * 0.07;
        const xPos = centerX + rb.xNorm * cWidth * fanFactor + turb;

        // Ribbon length stretches proportionally to gravitational speed (motion blur streak)
        const streakLen =
          (rb.layer === 0 ? 75 : rb.layer === 1 ? 58 : 42) *
          (0.65 + gravityFactor * 0.75);

        const yTop = Math.max(crestY - 4, yPos - streakLen);
        const yBot = Math.min(plungeY + 10, yPos);

        // Edge feathering & aerated whitewater transition near the crest
        const edgeDist = 1 - Math.min(1, Math.abs(rb.xNorm) * 1.9);
        const crestAerated = Math.max(0, 1 - rb.y * 2.6); // extra foamy bright near top lip
        const alpha = rb.opacity * (0.35 + 0.65 * edgeDist);

        if (yBot > yTop) {
          const grad = ctx.createLinearGradient(xPos, yTop, xPos, yBot);
          if (rb.layer === 2 || crestAerated > 0.45) {
            grad.addColorStop(0, "rgba(255, 255, 255, 0)");
            grad.addColorStop(0.35, `rgba(220, 248, 255, ${alpha * 0.75})`);
            grad.addColorStop(0.82, `rgba(255, 255, 255, ${Math.min(0.95, alpha * 1.15)})`);
            grad.addColorStop(1, "rgba(255, 255, 255, 0)");
          } else {
            grad.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0)`);
            grad.addColorStop(0.35, `rgba(${r}, ${g}, ${b}, ${alpha * 0.65})`);
            grad.addColorStop(
              0.8,
              `rgba(${Math.min(255, r + 75)}, ${Math.min(255, g + 60)}, 255, ${alpha})`
            );
            grad.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);
          }

          ctx.fillStyle = grad;
          // Slightly thinner width as water stretches at high velocity
          const dynamicWidth = rb.width * (1.12 - rb.y * 0.28);
          ctx.fillRect(
            xPos - dynamicWidth * 0.5,
            yTop,
            dynamicWidth,
            yBot - yTop
          );
        }

        // Reset at plunge pool & trigger kinetic splash droplets
        if (rb.y >= 1.06) {
          rb.y = -Math.random() * 0.08;
          const chuteSpread = rb.layer === 0 ? 0.14 : rb.layer === 1 ? 0.095 : 0.065;
          rb.xNorm = Math.max(
            -0.49,
            Math.min(
              0.49,
              chuteCenters[rb.chuteIndex] + (Math.random() - 0.5) * 2 * chuteSpread
            )
          );

          if (
            drops.length < 160 &&
            Math.random() < 0.36 * curSplash * Math.min(1.9, curFlow)
          ) {
            const impactX = centerX + rb.xNorm * cWidth;
            const maxLife = 26 + Math.random() * 32;
            drops.push({
              x: impactX + (Math.random() - 0.5) * 18,
              y: plungeY + (Math.random() - 0.5) * 8,
              vx: (Math.random() - 0.5) * 4.2,
              vy: -(2.6 + Math.random() * 5.2) * Math.sqrt(curFlow),
              radius: 1.0 + Math.random() * 2.2,
              alpha: 0.5 + Math.random() * 0.45,
              life: 0,
              maxLife,
            });
          }
        }
      }

      // 4. Aerated rolling crest foam lip at the top ledge
      for (let c = 0; c < chuteCenters.length; c++) {
        const cx = centerX + chuteCenters[c] * cWidth;
        const lipRadius = (cWidth / chuteCenters.length) * 0.78;
        const lipGrad = ctx.createRadialGradient(
          cx,
          crestY + 4,
          2,
          cx,
          crestY + 12,
          lipRadius
        );
        lipGrad.addColorStop(0, "rgba(255, 255, 255, 0.52)");
        lipGrad.addColorStop(0.5, `rgba(${Math.min(255, r + 80)}, ${Math.min(255, g + 70)}, 255, 0.24)`);
        lipGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = lipGrad;
        ctx.beginPath();
        ctx.ellipse(cx, crestY + 6, lipRadius, 14, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // 5. Dark abyssal plunge pool basin with subsurface emerald/cyan scattering
      const poolGrad = ctx.createLinearGradient(0, plungeY - 6, 0, height);
      poolGrad.addColorStop(0, `rgba(${Math.min(255, r + 40)}, ${Math.min(255, g + 50)}, 255, 0.42)`);
      poolGrad.addColorStop(0.22, `rgba(${Math.floor(r * 0.45)}, ${Math.floor(g * 0.55)}, ${Math.floor(b * 0.7)}, 0.72)`);
      poolGrad.addColorStop(0.65, `rgba(${Math.floor(r * 0.18)}, ${Math.floor(g * 0.26)}, ${Math.floor(b * 0.38)}, 0.92)`);
      poolGrad.addColorStop(1, "#02060E");
      ctx.fillStyle = poolGrad;
      ctx.fillRect(0, plungeY, width, height - plungeY);

      ctx.save();
      ctx.globalCompositeOperation = "lighter";

      // Boiling whitewater foam rollers at the plunge pool impact zone
      const boilCount = 11;
      for (let bIdx = 0; bIdx < boilCount; bIdx++) {
        const bx =
          centerX +
          ((bIdx / (boilCount - 1)) - 0.5) * cWidth * 0.95 +
          Math.sin(time * 3.8 + bIdx * 1.7) * 10;
        const by = plungeY + 4 + Math.cos(time * 4.2 + bIdx * 2.3) * 4;
        const brx = (cWidth / boilCount) * (0.85 + 0.25 * Math.sin(time * 5 + bIdx));
        const bry = 8 + 4 * Math.cos(time * 4.5 + bIdx);

        const boilGrad = ctx.createRadialGradient(bx, by, 2, bx, by, brx);
        boilGrad.addColorStop(0, "rgba(255, 255, 255, 0.58)");
        boilGrad.addColorStop(0.55, `rgba(${Math.min(255, r + 75)}, ${Math.min(255, g + 65)}, 255, 0.25)`);
        boilGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = boilGrad;
        ctx.beginPath();
        ctx.ellipse(bx, by, brx, bry, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // Expanding elliptical water surface ripples propagating outward across the plunge pool
      for (let i = 0; i < poolRipples.length; i++) {
        const pr = poolRipples[i];
        pr.rx += pr.speed * (0.7 + curFlow * 0.45);
        if (pr.rx > pr.maxRx) {
          pr.rx = 6;
          pr.xNorm = (Math.random() - 0.5) * 0.95;
          pr.yOffset = 6 + Math.random() * (height - plungeY - 18);
        }
        const progress = pr.rx / pr.maxRx;
        const fade = (1 - progress) * Math.sin(progress * Math.PI);
        const rx = centerX + pr.xNorm * cWidth * 0.9;
        const ry = plungeY + pr.yOffset + progress * 18;

        ctx.beginPath();
        ctx.ellipse(
          rx,
          ry,
          pr.rx,
          Math.max(2, pr.rx * 0.14),
          0,
          0,
          Math.PI * 2
        );
        ctx.strokeStyle = `rgba(220, 248, 255, ${pr.alpha * fade})`;
        ctx.lineWidth = 1.3 * (1 - progress * 0.5);
        ctx.stroke();
      }

      // 6. Ballistic splash droplets & fine spray with gravity
      for (let i = drops.length - 1; i >= 0; i--) {
        const d = drops[i];
        d.x += d.vx;
        d.y += d.vy;
        d.vy += 0.18; // gravity
        d.life += 1;

        const lifeRatio = 1 - d.life / d.maxLife;
        if (lifeRatio <= 0 || d.y > height) {
          drops.splice(i, 1);
          continue;
        }

        ctx.beginPath();
        ctx.arc(d.x, d.y, d.radius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(235, 251, 255, ${d.alpha * lifeRatio})`;
        ctx.fill();
      }

      // 7. Rising volumetric mist banks catching top ambient light
      if (curMist > 0.01) {
        for (let i = 0; i < mistBanks.length; i++) {
          const m = mistBanks[i];
          const rise = ((time * 0.22 * m.speed + m.risePhase) % 1);
          const fade = Math.sin(rise * Math.PI);
          const mx =
            centerX +
            m.xNorm * cWidth * 0.62 +
            Math.sin(time * 0.65 + m.phase) * 28;
          const my = plungeY + m.yOffset - rise * 78;
          const rad = m.radius * (0.85 + rise * 0.35);

          const mistGrad = ctx.createRadialGradient(
            mx,
            my - rad * 0.18,
            4,
            mx,
            my,
            rad
          );
          const peakAlpha = 0.16 * curMist * fade;
          mistGrad.addColorStop(0, `rgba(235, 250, 255, ${peakAlpha})`);
          mistGrad.addColorStop(
            0.48,
            `rgba(${Math.min(255, r + 35)}, ${Math.min(255, g + 35)}, 255, ${peakAlpha * 0.58})`
          );
          mistGrad.addColorStop(1, "rgba(0, 0, 0, 0)");

          ctx.fillStyle = mistGrad;
          ctx.beginPath();
          ctx.arc(mx, my, rad, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      ctx.restore();

      rafId = requestAnimationFrame(render);
    };

    rafId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(rafId);
      ro.disconnect();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      data-fullscreen-scroll
      className={cn(
        "relative flex min-h-[520px] w-full flex-col justify-between overflow-hidden rounded-2xl border border-white/10 bg-[#020611] p-6 text-white shadow-2xl",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full"
      />

      {/* Subtle top-to-bottom vignette */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-gradient-to-b from-[#020611]/55 via-transparent to-[#020611]/75"
      />

      {children && (
        <div className="relative z-10 flex min-h-[520px] w-full flex-col">
          {children}
        </div>
      )}
    </div>
  );
}

export default Waterfall;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Compass, Zap, Sliders, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

export interface WormholeTunnelProps {
  /** Number of concentric depth rings in the wormhole conduit (default: 28) */
  ringCount?: number;
  /** Forward traversal speed multiplier through the tunnel (default: 1.0) */
  speed?: number;
  /** Starting HSL hue in degrees (0-360, default: 195) */
  baseHue?: number;
  /** Total hue shift range from throat to outer aperture (default: 90) */
  hueShift?: number;
  /** Helical twist multiplier applied across tunnel depth (default: 1.2) */
  twist?: number;
  /** Whether the wormhole throat bends toward pointer movement (default: true) */
  interactive?: boolean;
  /** Optional foreground content rendered over the tunnel */
  children?: React.ReactNode;
  /** Additional CSS classes for the root container */
  className?: string;
}

interface RelativisticStarStreak {
  angle: number;
  z: number; // 0 (throat) to 1 (camera)
  speedOffset: number;
  hueOffset: number;
  thickness: number;
  radialJitter: number;
}

interface PlasmaCloudPuff {
  angle: number;
  z: number;
  sizeFactor: number;
  hueShift: number;
  alpha: number;
}

const WORMHOLE_PRESETS = [
  { name: "Cherenkov Cyan", baseHue: 195, hueShift: 90, twist: 1.2, speed: 1.0 },
  { name: "Hyperdrive Magenta", baseHue: 295, hueShift: 110, twist: 1.8, speed: 1.4 },
  { name: "Chrono Gold", baseHue: 38, hueShift: 65, twist: 0.75, speed: 0.85 },
] as const;

export function WormholeTunnel({
  ringCount = 28,
  speed = 1.0,
  baseHue = 195,
  hueShift = 90,
  twist = 1.2,
  interactive = true,
  children,
  className,
}: WormholeTunnelProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [activeRings, setActiveRings] = useState(ringCount);
  const [activeSpeed, setActiveSpeed] = useState(speed);
  const [activeHue, setActiveHue] = useState(baseHue);
  const [activeHueShift, setActiveHueShift] = useState(hueShift);
  const [activeTwist, setActiveTwist] = useState(twist);
  const pointerRef = useRef<{ x: number; y: number; active: boolean }>({
    x: 0,
    y: 0,
    active: false,
  });

  useEffect(() => {
    setActiveRings(ringCount);
  }, [ringCount]);
  useEffect(() => {
    setActiveSpeed(speed);
  }, [speed]);
  useEffect(() => {
    setActiveHue(baseHue);
  }, [baseHue]);
  useEffect(() => {
    setActiveHueShift(hueShift);
  }, [hueShift]);
  useEffect(() => {
    setActiveTwist(twist);
  }, [twist]);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let width = container.clientWidth || 800;
    let height = container.clientHeight || 520;
    let dpr = Math.min(window.devicePixelRatio || 1, 2);

    const resize = () => {
      if (!container || !canvas) return;
      width = container.clientWidth || 800;
      height = container.clientHeight || 520;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(container);

    // Relativistic star streaks warping along the curved spacetime walls
    const starStreaks: RelativisticStarStreak[] = Array.from(
      { length: 150 },
      () => ({
        angle: Math.random() * Math.PI * 2,
        z: Math.random(),
        speedOffset: 0.65 + Math.random() * 0.85,
        hueOffset: (Math.random() - 0.5) * 45,
        thickness: 0.8 + Math.random() * 1.8,
        radialJitter: 0.88 + Math.random() * 0.28,
      })
    );

    // Volumetric plasma nebula clouds spiraling along the manifold
    const plasmaPuffs: PlasmaCloudPuff[] = Array.from({ length: 42 }, (_, i) => ({
      angle: (i / 42) * Math.PI * 6,
      z: i / 42,
      sizeFactor: 0.42 + (i % 5) * 0.12,
      hueShift: ((i % 7) - 3) * 14,
      alpha: 0.08 + (i % 4) * 0.035,
    }));

    let rafId = 0;
    let time = 0;
    let smoothTargetX = 0;
    let smoothTargetY = 0;

    const numRings = Math.max(12, Math.min(60, activeRings));
    const segments = 16;

    const render = () => {
      const dt = 0.008 * activeSpeed;
      time += dt;

      // Deep relativistic void with motion persistence
      ctx.fillStyle = "rgba(2, 4, 12, 0.34)";
      ctx.fillRect(0, 0, width, height);

      const cx = width * 0.5;
      const cy = height * 0.5;
      const maxRadius = Math.hypot(width, height) * 0.68;

      // Lissajous oscillation + interactive pointer steering for the throat
      const lissajousX = Math.sin(time * 2.1) * (width * 0.11);
      const lissajousY = Math.cos(time * 1.6) * (height * 0.09);

      const targetX =
        interactive && pointerRef.current.active
          ? pointerRef.current.x * (width * 0.25)
          : lissajousX;
      const targetY =
        interactive && pointerRef.current.active
          ? pointerRef.current.y * (height * 0.22)
          : lissajousY;

      smoothTargetX += (targetX - smoothTargetX) * 0.06;
      smoothTargetY += (targetY - smoothTargetY) * 0.06;

      // Helper to compute curved 3D manifold center and radius at normalized depth zNorm (0 = throat, 1 = camera)
      const sampleManifold = (zNorm: number) => {
        // Hyperbolic spacetime funnel profile: narrow throat flaring exponentially
        const scale = Math.pow(zNorm, 2.45);
        const radius = 8 + scale * maxRadius;
        const bendFactor = Math.pow(1 - zNorm, 1.48);
        const waveWobbleX =
          Math.sin(zNorm * Math.PI * 2.5 - time * 3.2) * 20 * bendFactor;
        const waveWobbleY =
          Math.cos(zNorm * Math.PI * 2.5 - time * 2.8) * 15 * bendFactor;

        return {
          x: cx + smoothTargetX * bendFactor + waveWobbleX,
          y: cy + smoothTargetY * bendFactor + waveWobbleY,
          radius,
          rotation: time * 0.95 + (1 - zNorm) * activeTwist * Math.PI * 1.55,
          hue: (activeHue + (1 - zNorm) * activeHueShift + 360) % 360,
        };
      };

      // 1. Volumetric Spiraling Plasma Nebula Clouds (Depth-Sorted Back-to-Front)
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      for (let i = 0; i < plasmaPuffs.length; i++) {
        const puff = plasmaPuffs[i];
        const zNorm = (puff.z + time * 0.85) % 1;
        const m = sampleManifold(zNorm);
        const theta = puff.angle + m.rotation * 1.15;
        const px = m.x + Math.cos(theta) * m.radius * 0.92;
        const py = m.y + Math.sin(theta) * m.radius * 0.92;
        const puffRadius = Math.max(18, m.radius * puff.sizeFactor);
        const depthFade = Math.sin(zNorm * Math.PI);
        const pHue = (m.hue + puff.hueShift + 360) % 360;

        const nebGrad = ctx.createRadialGradient(
          px,
          py,
          0,
          px,
          py,
          puffRadius
        );
        nebGrad.addColorStop(
          0,
          `hsla(${pHue.toFixed(1)}, 95%, 65%, ${(
            puff.alpha *
            depthFade *
            1.45
          ).toFixed(3)})`
        );
        nebGrad.addColorStop(
          0.48,
          `hsla(${((pHue + 28) % 360).toFixed(1)}, 90%, 48%, ${(
            puff.alpha *
            depthFade *
            0.65
          ).toFixed(3)})`
        );
        nebGrad.addColorStop(1, "rgba(0, 0, 0, 0)");

        ctx.fillStyle = nebGrad;
        ctx.beginPath();
        ctx.arc(px, py, puffRadius, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // 2. Curved Spacetime Manifold Geometry, Longitudinal Energy Filaments & Depth-Fog Occlusion
      const ringVertices: Array<{
        points: Array<{ x: number; y: number }>;
        cx: number;
        cy: number;
        radius: number;
        zNorm: number;
        hue: number;
        alpha: number;
      }> = [];

      const phase = (time * 1.45) % 1;

      for (let i = 0; i < numRings; i++) {
        const zNorm = (i + phase) / numRings;
        const m = sampleManifold(zNorm);
        // Depth fog attenuation near throat (zNorm -> 0) and smooth fade at camera clip (zNorm -> 1)
        const alpha =
          Math.sin(zNorm * Math.PI) * (0.14 + Math.pow(zNorm, 0.72) * 0.78);

        const points: Array<{ x: number; y: number }> = [];
        for (let s = 0; s < segments; s++) {
          const theta = m.rotation + (s / segments) * Math.PI * 2;
          const ripple =
            1 + 0.045 * Math.sin(s * 4 + time * 4.5 + zNorm * 9);
          points.push({
            x: m.x + Math.cos(theta) * m.radius * ripple,
            y: m.y + Math.sin(theta) * m.radius * ripple,
          });
        }

        ringVertices.push({
          points,
          cx: m.x,
          cy: m.y,
          radius: m.radius,
          zNorm,
          hue: m.hue,
          alpha,
        });
      }

      // Draw volumetric depth-fog shadow rings + glowing plasma filaments from back to front
      for (let i = 0; i < ringVertices.length - 1; i++) {
        const curr = ringVertices[i];
        const next = ringVertices[i + 1];

        // Subtle dark depth-fog occlusion band between rings to give 3D tubular solidity
        if (i % 2 === 0) {
          ctx.save();
          ctx.strokeStyle = `rgba(2, 4, 14, ${(
            (1 - curr.zNorm) *
            0.35
          ).toFixed(3)})`;
          ctx.lineWidth = Math.max(2, (next.radius - curr.radius) * 0.65);
          ctx.beginPath();
          ctx.arc(curr.cx, curr.cy, curr.radius, 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();
        }

        // Spiraling longitudinal plasma filaments connecting consecutive rings
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        const ribAlpha = Math.min(curr.alpha, next.alpha) * 0.52;
        ctx.strokeStyle = `hsla(${curr.hue.toFixed(1)}, 95%, 66%, ${ribAlpha.toFixed(3)})`;
        ctx.lineWidth = 0.7 + curr.zNorm * 1.65;

        ctx.beginPath();
        for (let s = 0; s < segments; s++) {
          const nextIdx = (s + 1) % segments; // Helical diagonal filament weave
          ctx.moveTo(curr.points[s].x, curr.points[s].y);
          ctx.lineTo(next.points[nextIdx].x, next.points[nextIdx].y);
        }
        ctx.stroke();
        ctx.restore();
      }

      // Draw concentric curved energy rings with chromatic aberration near the throat
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < ringVertices.length; i++) {
        const ring = ringVertices[i];
        const pts = ring.points;
        const lw = 0.9 + Math.pow(ring.zNorm, 1.55) * 2.6;

        const traceSmoothRing = (offsetX: number, offsetY: number) => {
          ctx.beginPath();
          for (let s = 0; s < segments; s++) {
            const p0 = pts[s];
            const p1 = pts[(s + 1) % segments];
            const midX = (p0.x + p1.x) * 0.5 + offsetX;
            const midY = (p0.y + p1.y) * 0.5 + offsetY;
            if (s === 0) {
              const prev = pts[segments - 1];
              ctx.moveTo(
                (prev.x + p0.x) * 0.5 + offsetX,
                (prev.y + p0.y) * 0.5 + offsetY
              );
            }
            ctx.quadraticCurveTo(p0.x + offsetX, p0.y + offsetY, midX, midY);
          }
          ctx.closePath();
        };

        // Relativistic chromatic aberration split (cyan vs magenta/red channel offset)
        const chromaShift = (1 - ring.zNorm) * 3.2 + ring.zNorm * 1.4;
        ctx.strokeStyle = `hsla(${((ring.hue - 32 + 360) % 360).toFixed(
          1
        )}, 100%, 62%, ${(ring.alpha * 0.42).toFixed(3)})`;
        ctx.lineWidth = lw * 1.15;
        traceSmoothRing(-chromaShift, 0);
        ctx.stroke();

        ctx.strokeStyle = `hsla(${((ring.hue + 32) % 360).toFixed(
          1
        )}, 100%, 62%, ${(ring.alpha * 0.42).toFixed(3)})`;
        traceSmoothRing(chromaShift, 0);
        ctx.stroke();

        // Primary white-hot/tinted geodesic ring
        ctx.strokeStyle = `hsla(${ring.hue.toFixed(1)}, 98%, 74%, ${ring.alpha.toFixed(3)})`;
        ctx.lineWidth = lw;
        traceSmoothRing(0, 0);
        ctx.stroke();
      }

      // 3. Relativistic Star Streaks Warping Along the Tunnel Walls
      for (let i = 0; i < starStreaks.length; i++) {
        const st = starStreaks[i];
        st.z += 0.011 * Math.max(0.15, activeSpeed) * st.speedOffset;
        if (st.z >= 1) {
          st.z = 0.02 + Math.random() * 0.08;
          st.angle = Math.random() * Math.PI * 2;
        }

        const zTail = Math.max(0.01, st.z - (0.035 + st.z * 0.085) * Math.max(0.3, activeSpeed));
        const mHead = sampleManifold(st.z);
        const mTail = sampleManifold(zTail);

        const aHead = st.angle + mHead.rotation * 0.85;
        const aTail = st.angle + mTail.rotation * 0.85;

        const hx = mHead.x + Math.cos(aHead) * mHead.radius * st.radialJitter;
        const hy = mHead.y + Math.sin(aHead) * mHead.radius * st.radialJitter;
        const tx = mTail.x + Math.cos(aTail) * mTail.radius * st.radialJitter;
        const ty = mTail.y + Math.sin(aTail) * mTail.radius * st.radialJitter;

        const streakAlpha = Math.sin(st.z * Math.PI) * 0.9;
        const sHue = (mHead.hue + st.hueOffset + 360) % 360;

        const sGrad = ctx.createLinearGradient(hx, hy, tx, ty);
        sGrad.addColorStop(0, `rgba(255, 255, 255, ${streakAlpha.toFixed(3)})`);
        sGrad.addColorStop(
          0.35,
          `hsla(${sHue.toFixed(1)}, 100%, 75%, ${(streakAlpha * 0.8).toFixed(3)})`
        );
        sGrad.addColorStop(1, "rgba(0, 0, 0, 0)");

        ctx.strokeStyle = sGrad;
        ctx.lineWidth = st.thickness * (0.5 + st.z * 1.4);
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(hx, hy);
        ctx.lineTo(tx, ty);
        ctx.stroke();
      }

      // 4. Vanishing Throat Gravitational Lensing Singularity & Chromatic Caustic Ring
      const throat = sampleManifold(0.02);
      const throatHue = (activeHue + activeHueShift) % 360;

      // Outer lensing caustic halo
      const outerThroatGlow = ctx.createRadialGradient(
        throat.x,
        throat.y,
        4,
        throat.x,
        throat.y,
        135
      );
      outerThroatGlow.addColorStop(0, "rgba(255, 255, 255, 1)");
      outerThroatGlow.addColorStop(
        0.16,
        `hsla(${throatHue.toFixed(1)}, 100%, 78%, 0.85)`
      );
      outerThroatGlow.addColorStop(
        0.42,
        `hsla(${activeHue.toFixed(1)}, 95%, 58%, 0.35)`
      );
      outerThroatGlow.addColorStop(1, "rgba(0, 0, 0, 0)");

      ctx.fillStyle = outerThroatGlow;
      ctx.beginPath();
      ctx.arc(throat.x, throat.y, 135, 0, Math.PI * 2);
      ctx.fill();

      // Dark event-horizon aperture pinprick inside the wormhole throat surrounded by an Einstein ring
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "#02030A";
      ctx.beginPath();
      ctx.arc(throat.x, throat.y, 9, 0, Math.PI * 2);
      ctx.fill();

      ctx.globalCompositeOperation = "lighter";
      ctx.strokeStyle = "rgba(255, 255, 255, 0.92)";
      ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.arc(throat.x, throat.y, 10.5, 0, Math.PI * 2);
      ctx.stroke();

      ctx.restore();

      rafId = requestAnimationFrame(render);
    };

    ctx.fillStyle = "#02040C";
    ctx.fillRect(0, 0, width, height);
    rafId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(rafId);
      observer.disconnect();
    };
  }, [activeRings, activeSpeed, activeHue, activeHueShift, activeTwist, interactive]);

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const nx = ((e.clientX - rect.left) / rect.width - 0.5) * 2;
    const ny = ((e.clientY - rect.top) / rect.height - 0.5) * 2;
    pointerRef.current = { x: nx, y: ny, active: true };
  };

  const handlePointerLeave = () => {
    pointerRef.current.active = false;
  };

  return (
    <div
      ref={containerRef}
      data-fullscreen-scroll
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      className={cn(
        "relative w-full min-h-[520px] overflow-hidden rounded-2xl bg-[#02040C] text-white select-none",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full"
      />

      {children && (
        <div className="relative z-10 flex min-h-[520px] w-full flex-col">
          {children}
        </div>
      )}
    </div>
  );
}

export default WormholeTunnel;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}
